const SHELL_EXEC_TRUNCATE_BYTES: usize = 131_072; // 128 KB

fn mcp_schema_codex_context() -> bool {
    let client = std::env::var("AGENT_BRIDGE_CLIENT").ok();
    let toolset = std::env::var("AGENT_BRIDGE_TOOLSET").ok();
    let codex_host = std::env::var("AGENT_BRIDGE_CODEX_HOST").ok();

    client
        .as_deref()
        .map(normalize_tool_policy_value)
        .is_some_and(|v| v.starts_with("codex"))
        || toolset
            .as_deref()
            .map(normalize_tool_policy_value)
            .is_some_and(|v| v.starts_with("codex"))
        || codex_host.as_deref().is_some_and(|v| !v.trim().is_empty())
}

fn append_codex_native_hint(base: &str, codex_note: &str, codex_context: bool) -> String {
    if codex_context {
        format!("{base} Codex note: {codex_note}")
    } else {
        base.to_string()
    }
}

fn mcp_schema_description(base: &str, codex_note: &str) -> String {
    append_codex_native_hint(base, codex_note, mcp_schema_codex_context())
}

fn compact_mcp_output_default() -> bool {
    let policy = ToolPolicy::from_env();
    compact_mcp_output_default_for_policy(policy)
}

fn compact_mcp_output_default_for_policy(policy: ToolPolicy) -> bool {
    matches!(policy.set, ToolSet::CodexEssential | ToolSet::CodexLean)
        || matches!(policy.profile(), ToolProfile::Compact)
}

pub(crate) fn truncate_chars(s: &str, max_chars: usize) -> (String, bool, usize) {
    let total = s.chars().count();
    if max_chars == 0 || total <= max_chars {
        (s.to_string(), false, total)
    } else {
        let mut out: String = s.chars().take(max_chars).collect();
        out.push('…');
        (out, true, total)
    }
}

pub(crate) fn project_forum_posts(
    posts: &[ForumPostRecord],
    body_max_chars: usize,
    include_refs: bool,
) -> (Vec<Value>, usize) {
    let mut truncated = 0usize;
    let out = posts
        .iter()
        .map(|post| {
            let (body, body_truncated, body_total_chars) =
                truncate_chars(&post.body, body_max_chars);
            if body_truncated {
                truncated += 1;
            }
            let mut obj = Map::new();
            obj.insert("id".to_string(), json!(post.id));
            obj.insert("thread_id".to_string(), json!(post.thread_id));
            obj.insert("author".to_string(), json!(post.author));
            obj.insert("kind".to_string(), json!(post.kind));
            obj.insert("body".to_string(), json!(body));
            if body_truncated {
                obj.insert("body_truncated".to_string(), json!(true));
                obj.insert("body_total_chars".to_string(), json!(body_total_chars));
            }
            if include_refs {
                obj.insert("refs".to_string(), post.refs.clone());
            } else if !post.refs.is_null() {
                obj.insert("refs_omitted".to_string(), json!(true));
            }
            obj.insert("created_at".to_string(), json!(post.created_at));
            Value::Object(obj)
        })
        .collect();
    (out, truncated)
}

fn capabilities_summary(capabilities: &Value) -> Value {
    let Some(obj) = capabilities.as_object() else {
        return json!({"type": capabilities_type_label(capabilities)});
    };
    let mut keys: Vec<&str> = obj.keys().map(|s| s.as_str()).collect();
    keys.sort_unstable();
    let mut out = Map::new();
    out.insert("keys".to_string(), json!(keys));
    if let Some(avatar) = obj.get("avatar_state").and_then(|v| v.as_object()) {
        let mut compact = Map::new();
        for key in [
            "mode",
            "activity_state",
            "focus",
            "next_action",
            "risk_level",
            "updated_at",
            "source",
        ] {
            if let Some(v) = avatar.get(key) {
                compact.insert(key.to_string(), v.clone());
            }
        }
        if let Some(policy) = avatar.get("voice_policy").and_then(|v| v.as_object()) {
            if let Some(default_silent) = policy.get("default_silent") {
                compact.insert("voice_default_silent".to_string(), default_silent.clone());
            }
        }
        if !compact.is_empty() {
            out.insert("avatar_state".to_string(), Value::Object(compact));
        }
    }
    if let Some(pet) = obj.get("pet_state").and_then(|v| v.as_object()) {
        let mut compact = Map::new();
        for key in [
            "mode",
            "activity_state",
            "focus",
            "next_action",
            "risk_level",
        ] {
            if let Some(v) = pet.get(key) {
                compact.insert(key.to_string(), v.clone());
            }
        }
        if !compact.is_empty() {
            out.insert("pet_state".to_string(), Value::Object(compact));
        }
    }
    Value::Object(out)
}

fn capabilities_type_label(v: &Value) -> &'static str {
    match v {
        Value::Null => "null",
        Value::Bool(_) => "bool",
        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

fn project_agent_presence_rows(
    rows: &[AgentPresenceRecord],
    include_capabilities: bool,
    include_skills: bool,
) -> (Vec<Value>, usize, usize) {
    let mut capabilities_omitted = 0usize;
    let mut skills_omitted = 0usize;
    let out = rows
        .iter()
        .map(|row| {
            let mut obj = Map::new();
            obj.insert("session_id".to_string(), json!(row.session_id));
            obj.insert("name".to_string(), json!(row.name));
            if let Some(v) = &row.description {
                obj.insert("description".to_string(), json!(v));
            }
            if let Some(v) = &row.version {
                obj.insert("version".to_string(), json!(v));
            }
            if let Some(v) = &row.url {
                obj.insert("url".to_string(), json!(v));
            }
            if include_capabilities {
                if let Some(v) = &row.capabilities {
                    obj.insert("capabilities".to_string(), v.clone());
                }
            } else if let Some(v) = &row.capabilities {
                capabilities_omitted += 1;
                obj.insert("capabilities_omitted".to_string(), json!(true));
                obj.insert("capabilities_summary".to_string(), capabilities_summary(v));
            }
            if include_skills {
                if let Some(v) = &row.skills {
                    obj.insert("skills".to_string(), v.clone());
                }
            } else if row.skills.is_some() {
                skills_omitted += 1;
                obj.insert("skills_omitted".to_string(), json!(true));
            }
            obj.insert("node".to_string(), json!(row.node));
            obj.insert("project".to_string(), json!(row.project));
            obj.insert("role".to_string(), json!(row.role));
            if let Some(v) = &row.tag {
                obj.insert("tag".to_string(), json!(v));
            }
            if let Some(v) = &row.cwd {
                obj.insert("cwd".to_string(), json!(v));
            }
            if let Some(v) = row.pid {
                obj.insert("pid".to_string(), json!(v));
            }
            obj.insert("started_at".to_string(), json!(row.started_at));
            obj.insert(
                "last_heartbeat_at".to_string(),
                json!(row.last_heartbeat_at),
            );
            Value::Object(obj)
        })
        .collect();
    (out, capabilities_omitted, skills_omitted)
}

pub struct ShellExecTool {
    hub: Hub,
}

impl ShellExecTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for ShellExecTool {
    fn name(&self) -> &'static str {
        "shell_exec"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: mcp_schema_description(
                "Run a shell command synchronously; returns exit code, stdout, \
                 stderr, wall-clock duration. Unlike terminal_send_keys this captures \
                 output directly; no PTY needed. stdout/stderr truncated at 128 KB. \
                 Default timeout 30 s, max 300 s.",
                "Prefer Codex native shell/exec tools for ordinary local commands; use \
                 this Agent-Bridge tool only when you need MCP-level execution, dispatch \
                 telemetry, or Agent-Bridge security/env limits.",
            ),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cmd": {
                        "type": "string",
                        "description": "Shell command to run (executed via sh -c)."
                    },
                    "cwd": {
                        "type": "string",
                        "description": "Working directory. Defaults to the agent-bridge process cwd."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 1000,
                        "maximum": 300000,
                        "default": 30000,
                        "description": "Milliseconds before the process is killed."
                    },
                    "env": {
                        "type": "object",
                        "description": "Extra environment variables to inject (string keys + values).",
                        "additionalProperties": { "type": "string" }
                    }
                },
                "required": ["cmd"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let cmd = match args.get("cmd").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => return Ok(ToolResult::error("missing or empty 'cmd'")),
        };
        let timeout_max = self.hub.security.shell_exec_timeout_max_ms;
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(30_000)
            .clamp(1_000, timeout_max);

        let mut child = {
            let mut builder = TokioCommand::new("sh");
            builder.arg("-c").arg(&cmd);
            builder.stdout(std::process::Stdio::piped());
            builder.stderr(std::process::Stdio::piped());
            if let Some(cwd) = args.get("cwd").and_then(|v| v.as_str()) {
                builder.current_dir(cwd);
            }
            if let Some(env_map) = args.get("env").and_then(|v| v.as_object()) {
                for (k, v) in env_map {
                    if let Some(val) = v.as_str() {
                        builder.env(k, val);
                    }
                }
            }
            match builder.spawn() {
                Ok(c) => c,
                Err(e) => return Ok(ToolResult::error(format!("spawn failed: {e}"))),
            }
        };

        let started = Instant::now();
        let deadline = Duration::from_millis(timeout_ms);

        // Drain stdout + stderr in background tasks so the process doesn't block on full pipes.
        use tokio::io::AsyncReadExt as _;
        let mut stdout_pipe = child.stdout.take().expect("stdout piped");
        let mut stderr_pipe = child.stderr.take().expect("stderr piped");
        let stdout_task = tokio::spawn(async move {
            let mut buf = Vec::new();
            let _ = stdout_pipe.read_to_end(&mut buf).await;
            buf
        });
        let stderr_task = tokio::spawn(async move {
            let mut buf = Vec::new();
            let _ = stderr_pipe.read_to_end(&mut buf).await;
            buf
        });

        let timed_out = tokio::time::timeout(deadline, child.wait()).await;
        let duration_ms = started.elapsed().as_millis() as u64;

        let exit_code = match timed_out {
            Err(_) => {
                child.start_kill().ok();
                stdout_task.abort();
                stderr_task.abort();
                return Ok(ToolResult::json_text(&json!({
                    "exit_code": -1,
                    "stdout": "",
                    "stderr": format!("killed after {timeout_ms} ms timeout"),
                    "duration_ms": duration_ms,
                    "truncated": false
                })));
            }
            Ok(Err(e)) => return Ok(ToolResult::error(format!("wait failed: {e}"))),
            Ok(Ok(status)) => status.code().unwrap_or(-1),
        };

        let stdout_bytes = stdout_task.await.unwrap_or_default();
        let stderr_bytes = stderr_task.await.unwrap_or_default();
        let (stdout_str, stdout_truncated) = lossy_truncate(&stdout_bytes);
        let (stderr_str, stderr_truncated) = lossy_truncate(&stderr_bytes);

        Ok(ToolResult::json_text(&json!({
            "exit_code": exit_code,
            "stdout": stdout_str,
            "stderr": stderr_str,
            "duration_ms": duration_ms,
            "truncated": stdout_truncated || stderr_truncated
        })))
    }
}

fn lossy_truncate(bytes: &[u8]) -> (String, bool) {
    if bytes.len() <= SHELL_EXEC_TRUNCATE_BYTES {
        (String::from_utf8_lossy(bytes).into_owned(), false)
    } else {
        let s = String::from_utf8_lossy(&bytes[..SHELL_EXEC_TRUNCATE_BYTES]).into_owned();
        (
            format!(
                "{s}\n[... truncated at {} KB]",
                SHELL_EXEC_TRUNCATE_BYTES / 1024
            ),
            true,
        )
    }
}

// ===========================================================================
//                              desktop_snapshot
// ===========================================================================

pub struct DesktopSnapshotTool {
    _hub: Hub,
}

impl DesktopSnapshotTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for DesktopSnapshotTool {
    fn name(&self) -> &'static str {
        "desktop_snapshot"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only Linux desktop structure snapshot. Wraps \
                 scripts/desktop_snapshot.py and returns sway outputs/windows plus optional \
                 AT-SPI semantics. It does not click, type, move windows, or expose \
                 --activate-a11y; screenshots are opt-in to avoid surprise file writes."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": {
                        "type": "string",
                        "description": "Workspace/repo root used to resolve scripts/desktop_snapshot.py. Defaults to the MCP process cwd, then the build-time repo root."
                    },
                    "script_path": {
                        "type": "string",
                        "description": "Optional explicit desktop_snapshot.py path. Use mainly for tests or alternate checkouts."
                    },
                    "include_screenshot": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, allow grim to write per-output PNG files. Default false keeps the MCP call non-mutating except process execution."
                    },
                    "screenshot_dir": {
                        "type": "string",
                        "description": "Directory for PNG screenshots when include_screenshot=true."
                    },
                    "include_atspi": {
                        "type": "boolean",
                        "default": true,
                        "description": "Collect AT-SPI semantic elements when available. This does not enable global a11y."
                    },
                    "max_elements": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 1000,
                        "default": 120,
                        "description": "Cap AT-SPI elements per app."
                    },
                    "atspi_budget": {
                        "type": "number",
                        "minimum": 0.25,
                        "maximum": 10.0,
                        "default": 2.0,
                        "description": "Per-app AT-SPI traversal budget in seconds."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 1000,
                        "maximum": 60000,
                        "default": 15000,
                        "description": "Milliseconds before the snapshot process is killed."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(15_000)
            .clamp(1_000, 60_000);
        let include_screenshot = args
            .get("include_screenshot")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let include_atspi = args
            .get("include_atspi")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let max_elements = args
            .get("max_elements")
            .and_then(|v| v.as_u64())
            .unwrap_or(120)
            .clamp(1, 1000);
        let atspi_budget = args
            .get("atspi_budget")
            .and_then(|v| v.as_f64())
            .unwrap_or(2.0)
            .clamp(0.25, 10.0);

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = desktop_snapshot_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(desktop_snapshot_error(json!({
                "code": "script_missing",
                "message": format!("desktop_snapshot.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = TokioCommand::new(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script).arg("--compact");
        if !include_screenshot {
            cmd.arg("--no-screenshot");
        } else if let Some(dir) = args.get("screenshot_dir").and_then(|v| v.as_str()) {
            cmd.arg("--screenshot-dir").arg(dir);
        }
        if !include_atspi {
            cmd.arg("--no-atspi");
        }
        cmd.arg("--max-elements").arg(max_elements.to_string());
        cmd.arg("--atspi-budget").arg(atspi_budget.to_string());
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(desktop_snapshot_error(json!({
                        "code": "timeout",
                        "message": format!("desktop_snapshot exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(desktop_snapshot_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        if !output.status.success() {
            return Ok(desktop_snapshot_error(json!({
                "code": "script_failed",
                "exit_code": output.status.code().unwrap_or(-1),
                "stderr": stderr,
                "stdout": stdout,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            })));
        }

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": true,
                            "include_screenshot": include_screenshot,
                            "include_atspi": include_atspi,
                            "duration_ms": duration_ms,
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                Ok(ToolResult::json_text(&payload))
            }
            Err(e) => Ok(desktop_snapshot_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn desktop_snapshot_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_DESKTOP_SNAPSHOT_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/desktop_snapshot.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/desktop_snapshot.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/desktop_snapshot.py")
}

fn desktop_snapshot_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "desktop_snapshot_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//                            vision_grounding_ocr
// ===========================================================================

pub struct VisionGroundingOcrTool {
    _hub: Hub,
}

impl VisionGroundingOcrTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for VisionGroundingOcrTool {
    fn name(&self) -> &'static str {
        "vision_grounding_ocr"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Run the non-mutating OCR vision grounding reference runner. \
                 It reads an existing image plus desktop_snapshot metadata and returns \
                 `vision_grounding_result.v0` candidates; it never clicks, types, takes \
                 screenshots, or controls the desktop."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": {
                        "type": "string",
                        "description": "Workspace/repo root used to resolve scripts/vision_grounding_ocr.py. Defaults to the MCP process cwd, then the build-time repo root."
                    },
                    "script_path": {
                        "type": "string",
                        "description": "Optional explicit vision_grounding_ocr.py path. Use mainly for tests or alternate checkouts."
                    },
                    "image": {
                        "type": "string",
                        "description": "Existing PNG/JPEG image path to OCR. The tool does not capture screenshots."
                    },
                    "engine": {
                        "type": "string",
                        "enum": ["tesseract", "fixture-tsv", "none"],
                        "default": "tesseract"
                    },
                    "fixture_tsv": {
                        "type": "string",
                        "description": "TSV fixture path when engine=fixture-tsv."
                    },
                    "request_id": { "type": "string" },
                    "snapshot_id": {
                        "type": "string",
                        "description": "desktop_snapshot snapshot id associated with this image."
                    },
                    "snapshot_hash": {
                        "type": "string",
                        "description": "Hash of the source desktop_snapshot payload."
                    },
                    "snapshot_schema": {
                        "type": "string",
                        "default": "desktop_snapshot/v0.5"
                    },
                    "snapshot_captured_at": { "type": "string" },
                    "image_hash": { "type": "string" },
                    "image_kind": {
                        "type": "string",
                        "enum": ["desktop", "output", "window"],
                        "default": "window"
                    },
                    "coordinate_space": {
                        "type": "string",
                        "enum": ["desktop", "output", "window"],
                        "default": "window"
                    },
                    "output": { "type": "string" },
                    "crop_rect": {
                        "type": "string",
                        "description": "Optional x,y,width,height crop rect."
                    },
                    "window_id": { "type": "integer" },
                    "pid": { "type": "integer" },
                    "app_id": { "type": "string" },
                    "title_hash": { "type": "string" },
                    "window_rect": {
                        "type": "string",
                        "description": "Optional x,y,width,height target window rect."
                    },
                    "task": { "type": "string", "default": "find text" },
                    "hint_text": { "type": "string" },
                    "hint_role": { "type": "string", "default": "unknown" },
                    "language": { "type": "string", "default": "auto" },
                    "engine_timeout_secs": {
                        "type": "number",
                        "minimum": 0.5,
                        "maximum": 60.0,
                        "default": 8.0,
                        "description": "Timeout forwarded to the OCR engine."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 1000,
                        "maximum": 90000,
                        "default": 20000,
                        "description": "Milliseconds before the wrapper process is killed."
                    }
                },
                "required": ["image", "snapshot_id", "snapshot_hash"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let image = match required_str_arg(&args, "image") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let snapshot_id = match required_str_arg(&args, "snapshot_id") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let snapshot_hash = match required_str_arg(&args, "snapshot_hash") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let engine = args
            .get("engine")
            .and_then(|v| v.as_str())
            .unwrap_or("tesseract");
        if !matches!(engine, "tesseract" | "fixture-tsv" | "none") {
            return Ok(ToolResult::error(
                "engine must be tesseract, fixture-tsv, or none",
            ));
        }
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(20_000)
            .clamp(1_000, 90_000);
        let engine_timeout_secs = args
            .get("engine_timeout_secs")
            .and_then(|v| v.as_f64())
            .unwrap_or(8.0)
            .clamp(0.5, 60.0);

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = vision_grounding_ocr_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(vision_grounding_ocr_error(json!({
                "code": "script_missing",
                "message": format!("vision_grounding_ocr.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = TokioCommand::new(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script)
            .arg("--compact")
            .arg("--image")
            .arg(image)
            .arg("--engine")
            .arg(engine)
            .arg("--snapshot-id")
            .arg(snapshot_id)
            .arg("--snapshot-hash")
            .arg(snapshot_hash)
            .arg("--timeout")
            .arg(engine_timeout_secs.to_string());

        push_optional_str_arg(&mut cmd, &args, "fixture_tsv", "--fixture-tsv");
        push_optional_str_arg(&mut cmd, &args, "request_id", "--request-id");
        push_optional_str_arg(&mut cmd, &args, "snapshot_schema", "--snapshot-schema");
        push_optional_str_arg(
            &mut cmd,
            &args,
            "snapshot_captured_at",
            "--snapshot-captured-at",
        );
        push_optional_str_arg(&mut cmd, &args, "image_hash", "--image-hash");
        push_optional_str_arg(&mut cmd, &args, "image_kind", "--image-kind");
        push_optional_str_arg(&mut cmd, &args, "coordinate_space", "--coordinate-space");
        push_optional_str_arg(&mut cmd, &args, "output", "--output");
        push_optional_str_arg(&mut cmd, &args, "crop_rect", "--crop-rect");
        push_optional_value_arg(&mut cmd, &args, "window_id", "--window-id");
        push_optional_value_arg(&mut cmd, &args, "pid", "--pid");
        push_optional_str_arg(&mut cmd, &args, "app_id", "--app-id");
        push_optional_str_arg(&mut cmd, &args, "title_hash", "--title-hash");
        push_optional_str_arg(&mut cmd, &args, "window_rect", "--window-rect");
        push_optional_str_arg(&mut cmd, &args, "task", "--task");
        push_optional_str_arg(&mut cmd, &args, "hint_text", "--hint-text");
        push_optional_str_arg(&mut cmd, &args, "hint_role", "--hint-role");
        push_optional_str_arg(&mut cmd, &args, "language", "--language");

        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(vision_grounding_ocr_error(json!({
                        "code": "timeout",
                        "message": format!("vision_grounding_ocr exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(vision_grounding_ocr_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        if !output.status.success() {
            return Ok(vision_grounding_ocr_error(json!({
                "code": "script_failed",
                "exit_code": output.status.code().unwrap_or(-1),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            })));
        }

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": true,
                            "engine": engine,
                            "duration_ms": duration_ms,
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                Ok(ToolResult::json_text(&payload))
            }
            Err(e) => Ok(vision_grounding_ocr_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn required_str_arg(args: &Value, key: &str) -> std::result::Result<String, String> {
    match args.get(key).and_then(|v| v.as_str()) {
        Some(v) if !v.trim().is_empty() => Ok(v.to_string()),
        _ => Err(format!("missing or empty '{key}'")),
    }
}

fn push_optional_str_arg(cmd: &mut TokioCommand, args: &Value, key: &str, flag: &str) {
    if let Some(value) = args.get(key).and_then(|v| v.as_str()) {
        if !value.trim().is_empty() {
            cmd.arg(flag).arg(value);
        }
    }
}

fn push_optional_value_arg(cmd: &mut TokioCommand, args: &Value, key: &str, flag: &str) {
    if let Some(value) = args.get(key) {
        if let Some(n) = value.as_i64() {
            cmd.arg(flag).arg(n.to_string());
        } else if let Some(s) = value.as_str() {
            if !s.trim().is_empty() {
                cmd.arg(flag).arg(s);
            }
        }
    }
}

fn vision_grounding_ocr_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_VISION_GROUNDING_OCR_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/vision_grounding_ocr.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/vision_grounding_ocr.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/vision_grounding_ocr.py")
}

fn vision_grounding_ocr_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "vision_grounding_ocr_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//                              desktop_action
// ===========================================================================

pub struct DesktopActionTool {
    _hub: Hub,
}

impl DesktopActionTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for DesktopActionTool {
    fn name(&self) -> &'static str {
        "desktop_action"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Gated Linux desktop input injection (ISOLATED-ONLY MVP). Wraps \
                 scripts/desktop_action.py. Safe by construction: this MCP surface NEVER \
                 touches the real host desktop. An action runs only as (a) dry_run=true \
                 (logs intent + audits, injects nothing), or (b) isolated — a nested \
                 compositor addressed by a non-host `display` plus its `swaysock`, where \
                 absolute moveto/click go through the sway-IPC backend (which itself \
                 refuses physical-output sockets). Host-mutating injection (--confirm) is \
                 intentionally NOT exposed here and cannot be unlocked. Every call is \
                 audited to desktop_action_audit.jsonl."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "action": {
                        "type": "string",
                        "enum": ["type", "key", "move", "moveto", "click", "scroll"],
                        "description": "type/key need `text`; moveto needs x,y; move needs dx,dy; scroll needs dy[,dx]; click takes optional `button`."
                    },
                    "text": { "type": "string", "description": "For type (literal text) or key (keysym, e.g. Return, ctrl+c)." },
                    "x": { "type": "integer", "description": "Absolute X for moveto (nested compositor coords)." },
                    "y": { "type": "integer", "description": "Absolute Y for moveto." },
                    "dx": { "type": "integer", "description": "Relative X for move, or horizontal scroll." },
                    "dy": { "type": "integer", "description": "Relative Y for move, or vertical scroll." },
                    "button": { "type": "string", "enum": ["left", "right", "middle"], "default": "left", "description": "Mouse button for click." },
                    "display": { "type": "string", "description": "Target WAYLAND_DISPLAY. Must be a nested (non-host) display for any real injection." },
                    "swaysock": { "type": "string", "description": "Nested sway IPC socket; required (with a non-host display) for any non-dry-run injection. Enables the isolated sway-IPC absolute backend." },
                    "dry_run": { "type": "boolean", "default": false, "description": "When true, log intent + audit but inject nothing. Allowed against any target." },
                    "cwd": { "type": "string", "description": "Repo root to resolve scripts/desktop_action.py." },
                    "script_path": { "type": "string", "description": "Explicit desktop_action.py path (tests / alternate checkouts)." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 30000, "default": 10000, "description": "Milliseconds before the action process is killed." }
                },
                "required": ["action"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let action = match args.get("action").and_then(|v| v.as_str()) {
            Some(a) if ["type", "key", "move", "moveto", "click", "scroll"].contains(&a) => {
                a.to_string()
            }
            Some(a) => {
                return Ok(desktop_action_error(json!({
                    "code": "bad_action",
                    "message": format!("unknown action {a}")
                })));
            }
            None => {
                return Ok(desktop_action_error(json!({
                    "code": "missing_action",
                    "message": "`action` is required"
                })));
            }
        };
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(10_000)
            .clamp(1_000, 30_000);
        let dry_run = args.get("dry_run").and_then(|v| v.as_bool()).unwrap_or(false);
        let display = args.get("display").and_then(|v| v.as_str());
        let swaysock = args.get("swaysock").and_then(|v| v.as_str());

        // SAFETY (isolated-only MVP): this surface never touches the host desktop.
        // Allowed iff dry_run, or isolated = a non-host display WITH its swaysock.
        let host_display = std::env::var("AB_HOST_WAYLAND_DISPLAY")
            .ok()
            .filter(|s| !s.trim().is_empty())
            .unwrap_or_else(|| "wayland-1".to_string());
        let is_isolated = swaysock.map(|s| !s.is_empty()).unwrap_or(false)
            && display.map(|d| !d.is_empty() && d != host_display).unwrap_or(false);
        if !dry_run && !is_isolated {
            return Ok(desktop_action_error(json!({
                "code": "host_mutation_not_exposed",
                "message": "this MCP exposes only dry_run or isolated (non-host display + swaysock) \
                            actions; host-desktop injection is not available here",
                "hint": "set dry_run:true, or provide a nested `display` (!= host) and its `swaysock`"
            })));
        }

        let need_text = matches!(action.as_str(), "type" | "key");
        let text = args.get("text").and_then(|v| v.as_str());
        if need_text && text.map(|t| t.is_empty()).unwrap_or(true) {
            return Ok(desktop_action_error(json!({
                "code": "missing_text",
                "message": format!("action {action} requires a non-empty `text`")
            })));
        }

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = desktop_action_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(desktop_action_error(json!({
                "code": "script_missing",
                "message": format!("desktop_action.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = TokioCommand::new(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script).arg(&action);
        match action.as_str() {
            "type" | "key" => {
                cmd.arg(text.unwrap_or(""));
            }
            "moveto" => {
                let x = args.get("x").and_then(|v| v.as_i64()).unwrap_or(0);
                let y = args.get("y").and_then(|v| v.as_i64()).unwrap_or(0);
                cmd.arg(x.to_string()).arg(y.to_string());
            }
            "move" => {
                let dx = args.get("dx").and_then(|v| v.as_i64()).unwrap_or(0);
                let dy = args.get("dy").and_then(|v| v.as_i64()).unwrap_or(0);
                cmd.arg(dx.to_string()).arg(dy.to_string());
            }
            "scroll" => {
                let dy = args.get("dy").and_then(|v| v.as_i64()).unwrap_or(0);
                let dx = args.get("dx").and_then(|v| v.as_i64()).unwrap_or(0);
                cmd.arg(dy.to_string()).arg(dx.to_string());
            }
            "click" => {
                if let Some(btn) = args.get("button").and_then(|v| v.as_str()) {
                    cmd.arg(btn);
                }
            }
            _ => {}
        }
        if let Some(d) = display {
            cmd.arg("--display").arg(d);
        }
        if let Some(s) = swaysock {
            cmd.arg("--swaysock").arg(s);
        }
        if dry_run {
            cmd.arg("--dry-run");
        }
        // NOTE: --confirm / --i-understand-this-touches-the-real-desktop are NEVER
        // passed by this MCP surface, so host injection cannot be unlocked here.
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(desktop_action_error(json!({
                        "code": "timeout",
                        "message": format!("desktop_action exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(desktop_action_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        // desktop_action.py prints a JSON record; nonzero exit = blocked/error.
        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": false,
                            "mode": if dry_run { "dry-run" } else { "isolated" },
                            "host_protected": true,
                            "duration_ms": duration_ms,
                            "exit_code": output.status.code().unwrap_or(-1),
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                let mut result = ToolResult::json_text(&payload);
                if !output.status.success() {
                    result.is_error = true;
                }
                Ok(result)
            }
            Err(e) => Ok(desktop_action_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "exit_code": output.status.code().unwrap_or(-1),
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn desktop_action_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_DESKTOP_ACTION_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/desktop_action.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/desktop_action.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/desktop_action.py")
}

fn desktop_action_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "desktop_action_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//                        mobile / Android ADB tools
// ===========================================================================

const MOBILE_UI_DUMP_PATH: &str = "/sdcard/agent_bridge_window.xml";
const MOBILE_DEFAULT_TIMEOUT_MS: u64 = 30_000;

#[derive(Debug, Clone)]
struct AdbCommandOutput {
    exit_code: i32,
    stdout: String,
    stderr: String,
    duration_ms: u64,
    truncated: bool,
}

impl AdbCommandOutput {
    fn ok(&self) -> bool {
        self.exit_code == 0
    }

    fn as_json(&self) -> Value {
        json!({
            "exit_code": self.exit_code,
            "stdout": self.stdout,
            "stderr": self.stderr,
            "duration_ms": self.duration_ms,
            "truncated": self.truncated,
        })
    }
}

#[derive(Debug, Clone)]
struct AdbBinaryOutput {
    exit_code: i32,
    stdout: Vec<u8>,
    stderr: String,
    duration_ms: u64,
    stderr_truncated: bool,
}

impl AdbBinaryOutput {
    fn ok(&self) -> bool {
        self.exit_code == 0
    }

    fn as_json(&self) -> Value {
        json!({
            "exit_code": self.exit_code,
            "stdout_bytes": self.stdout.len(),
            "stderr": self.stderr,
            "duration_ms": self.duration_ms,
            "stderr_truncated": self.stderr_truncated,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MobileDevice {
    serial: String,
    state: String,
    attrs: HashMap<String, String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct MobileBounds {
    left: i64,
    top: i64,
    right: i64,
    bottom: i64,
}

impl MobileBounds {
    fn center(self) -> (i64, i64) {
        ((self.left + self.right) / 2, (self.top + self.bottom) / 2)
    }

    fn as_json(self) -> Value {
        let (x, y) = self.center();
        json!({
            "left": self.left,
            "top": self.top,
            "right": self.right,
            "bottom": self.bottom,
            "center": { "x": x, "y": y },
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MobileUiNode {
    ordinal: usize,
    index: String,
    text: String,
    resource_id: String,
    class_name: String,
    package_name: String,
    content_desc: String,
    clickable: bool,
    enabled: bool,
    focusable: bool,
    focused: bool,
    scrollable: bool,
    bounds: Option<MobileBounds>,
}

impl MobileUiNode {
    fn has_semantic_label(&self) -> bool {
        !self.text.is_empty() || !self.resource_id.is_empty() || !self.content_desc.is_empty()
    }

    fn is_actionable(&self) -> bool {
        self.clickable || self.focusable || self.scrollable || self.has_semantic_label()
    }

    fn is_surface_view(&self) -> bool {
        self.class_name == "android.view.SurfaceView"
    }

    fn compact_json(&self) -> Value {
        let mut obj = Map::new();
        obj.insert("ordinal".into(), json!(self.ordinal));
        if !self.index.is_empty() {
            obj.insert("index".into(), json!(self.index));
        }
        if !self.text.is_empty() {
            obj.insert("text".into(), json!(self.text));
        }
        if !self.resource_id.is_empty() {
            obj.insert("resource_id".into(), json!(self.resource_id));
        }
        if !self.class_name.is_empty() {
            obj.insert("class".into(), json!(self.class_name));
        }
        if !self.package_name.is_empty() {
            obj.insert("package".into(), json!(self.package_name));
        }
        if !self.content_desc.is_empty() {
            obj.insert("content_desc".into(), json!(self.content_desc));
        }
        if self.clickable {
            obj.insert("clickable".into(), json!(true));
        }
        if self.focusable {
            obj.insert("focusable".into(), json!(true));
        }
        if self.focused {
            obj.insert("focused".into(), json!(true));
        }
        if self.scrollable {
            obj.insert("scrollable".into(), json!(true));
        }
        obj.insert("enabled".into(), json!(self.enabled));
        if let Some(bounds) = self.bounds {
            obj.insert("bounds".into(), bounds.as_json());
        }
        Value::Object(obj)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct MobileUiAnalysis {
    node_count: usize,
    semantic_node_count: usize,
    actionable_node_count: usize,
    surface_view_count: usize,
    focused_surface_view_count: usize,
    semantic_nodes: bool,
    canvas_only: bool,
    surface_dominated: bool,
}

impl MobileUiAnalysis {
    fn from_nodes(nodes: &[MobileUiNode]) -> Self {
        let semantic_node_count = nodes.iter().filter(|n| n.has_semantic_label()).count();
        let actionable_node_count = nodes.iter().filter(|n| n.is_actionable()).count();
        let surface_view_count = nodes.iter().filter(|n| n.is_surface_view()).count();
        let focused_surface_view_count = nodes
            .iter()
            .filter(|n| n.is_surface_view() && n.focused)
            .count();
        let semantic_nodes = semantic_node_count > 0;
        let canvas_only = surface_view_count > 0 && !semantic_nodes;
        let surface_dominated = surface_view_count > 0 && semantic_node_count <= 2;
        Self {
            node_count: nodes.len(),
            semantic_node_count,
            actionable_node_count,
            surface_view_count,
            focused_surface_view_count,
            semantic_nodes,
            canvas_only,
            surface_dominated,
        }
    }

    fn as_json(self) -> Value {
        json!({
            "node_count": self.node_count,
            "semantic_node_count": self.semantic_node_count,
            "actionable_node_count": self.actionable_node_count,
            "surface_view_count": self.surface_view_count,
            "focused_surface_view_count": self.focused_surface_view_count,
            "semantic_nodes": self.semantic_nodes,
            "canvas_only": self.canvas_only,
            "surface_dominated": self.surface_dominated,
            "hint": if self.canvas_only {
                "UIAutomator sees a SurfaceView/canvas shell but no semantic child controls; use screenshot or engine-side hooks for in-canvas targets."
            } else if self.surface_dominated {
                "UIAutomator sees a SurfaceView/canvas app with limited semantic overlays; selector actions may only work for native overlays."
            } else {
                "UIAutomator exposes semantic nodes; prefer selectors over coordinates when possible."
            },
        })
    }
}

#[derive(Debug, Clone, Default)]
struct MobileSelector {
    text: Option<String>,
    text_contains: Option<String>,
    resource_id: Option<String>,
    content_desc: Option<String>,
    class_name: Option<String>,
    package_name: Option<String>,
    clickable: Option<bool>,
    focused: Option<bool>,
    enabled: Option<bool>,
}

impl MobileSelector {
    fn from_value(value: &Value) -> std::result::Result<Self, String> {
        let Some(obj) = value.as_object() else {
            return Err("'selector' must be an object".to_string());
        };
        let selector = Self {
            text: obj
                .get("text")
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(str::to_string),
            text_contains: obj
                .get("text_contains")
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(str::to_string),
            resource_id: obj
                .get("resource_id")
                .or_else(|| obj.get("resource-id"))
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(str::to_string),
            content_desc: obj
                .get("content_desc")
                .or_else(|| obj.get("content-desc"))
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(str::to_string),
            class_name: obj
                .get("class")
                .or_else(|| obj.get("class_name"))
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(str::to_string),
            package_name: obj
                .get("package")
                .or_else(|| obj.get("package_name"))
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(str::to_string),
            clickable: obj.get("clickable").and_then(|v| v.as_bool()),
            focused: obj.get("focused").and_then(|v| v.as_bool()),
            enabled: obj.get("enabled").and_then(|v| v.as_bool()),
        };
        if selector.is_empty() {
            return Err("selector must include at least one matching field".to_string());
        }
        Ok(selector)
    }

    fn is_empty(&self) -> bool {
        self.text.is_none()
            && self.text_contains.is_none()
            && self.resource_id.is_none()
            && self.content_desc.is_none()
            && self.class_name.is_none()
            && self.package_name.is_none()
            && self.clickable.is_none()
            && self.focused.is_none()
            && self.enabled.is_none()
    }

    fn matches(&self, node: &MobileUiNode) -> bool {
        if let Some(expected) = &self.text {
            if &node.text != expected {
                return false;
            }
        }
        if let Some(expected) = &self.text_contains {
            if !node.text.contains(expected) {
                return false;
            }
        }
        if let Some(expected) = &self.resource_id {
            if &node.resource_id != expected {
                return false;
            }
        }
        if let Some(expected) = &self.content_desc {
            if &node.content_desc != expected {
                return false;
            }
        }
        if let Some(expected) = &self.class_name {
            if &node.class_name != expected {
                return false;
            }
        }
        if let Some(expected) = &self.package_name {
            if &node.package_name != expected {
                return false;
            }
        }
        if let Some(expected) = self.clickable {
            if node.clickable != expected {
                return false;
            }
        }
        if let Some(expected) = self.focused {
            if node.focused != expected {
                return false;
            }
        }
        if let Some(expected) = self.enabled {
            if node.enabled != expected {
                return false;
            }
        }
        true
    }
}

fn mobile_schema_serial() -> Value {
    json!({
        "type": "string",
        "description": "ADB serial. Required when multiple online devices are connected."
    })
}

fn mobile_schema_selector() -> Value {
    json!({
        "type": "object",
        "description": "UI Automator node selector. All supplied fields must match.",
        "properties": {
            "text": { "type": "string" },
            "text_contains": { "type": "string" },
            "resource_id": { "type": "string" },
            "resource-id": { "type": "string" },
            "content_desc": { "type": "string" },
            "content-desc": { "type": "string" },
            "class": { "type": "string" },
            "package": { "type": "string" },
            "clickable": { "type": "boolean" },
            "focused": { "type": "boolean" },
            "enabled": { "type": "boolean" }
        }
    })
}

fn adb_args(parts: &[&str]) -> Vec<String> {
    parts.iter().map(|s| (*s).to_string()).collect()
}

fn mobile_timeout_ms(args: &Value) -> u64 {
    args.get("timeout_ms")
        .and_then(|v| v.as_u64())
        .unwrap_or(MOBILE_DEFAULT_TIMEOUT_MS)
        .clamp(1_000, 120_000)
}

fn resolve_adb_bin() -> String {
    if let Ok(v) = std::env::var("AGENT_BRIDGE_ADB") {
        if !v.trim().is_empty() {
            return v;
        }
    }
    if let Ok(v) = std::env::var("ADB") {
        if !v.trim().is_empty() {
            return v;
        }
    }
    if let Ok(home) = std::env::var("ANDROID_HOME") {
        let candidate = PathBuf::from(home).join("platform-tools").join("adb");
        if candidate.exists() {
            return candidate.to_string_lossy().into_owned();
        }
    }
    for candidate in [
        "/opt/homebrew/share/android-commandlinetools/platform-tools/adb",
        "/opt/homebrew/bin/adb",
        "/usr/local/bin/adb",
    ] {
        if PathBuf::from(candidate).exists() {
            return candidate.to_string();
        }
    }
    "adb".to_string()
}

async fn run_adb_command(
    serial: Option<&str>,
    args: &[String],
    timeout_ms: u64,
) -> std::result::Result<AdbCommandOutput, String> {
    let mut cmd = TokioCommand::new(resolve_adb_bin());
    if let Some(serial) = serial.filter(|s| !s.trim().is_empty()) {
        cmd.arg("-s").arg(serial);
    }
    cmd.args(args);
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::piped());

    let started = Instant::now();
    let out = tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await;
    let duration_ms = started.elapsed().as_millis() as u64;
    let output = match out {
        Ok(Ok(output)) => output,
        Ok(Err(e)) => return Err(format!("spawn adb failed: {e}")),
        Err(_) => {
            return Ok(AdbCommandOutput {
                exit_code: -1,
                stdout: String::new(),
                stderr: format!("killed after {timeout_ms} ms timeout"),
                duration_ms,
                truncated: false,
            });
        }
    };
    let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
    let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);
    Ok(AdbCommandOutput {
        exit_code: output.status.code().unwrap_or(-1),
        stdout,
        stderr,
        duration_ms,
        truncated: stdout_truncated || stderr_truncated,
    })
}

async fn run_adb_binary_command(
    serial: Option<&str>,
    args: &[String],
    timeout_ms: u64,
) -> std::result::Result<AdbBinaryOutput, String> {
    let mut cmd = TokioCommand::new(resolve_adb_bin());
    if let Some(serial) = serial.filter(|s| !s.trim().is_empty()) {
        cmd.arg("-s").arg(serial);
    }
    cmd.args(args);
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::piped());

    let started = Instant::now();
    let out = tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await;
    let duration_ms = started.elapsed().as_millis() as u64;
    let output = match out {
        Ok(Ok(output)) => output,
        Ok(Err(e)) => return Err(format!("spawn adb failed: {e}")),
        Err(_) => {
            return Ok(AdbBinaryOutput {
                exit_code: -1,
                stdout: Vec::new(),
                stderr: format!("killed after {timeout_ms} ms timeout"),
                duration_ms,
                stderr_truncated: false,
            });
        }
    };
    let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);
    Ok(AdbBinaryOutput {
        exit_code: output.status.code().unwrap_or(-1),
        stdout: output.stdout,
        stderr,
        duration_ms,
        stderr_truncated,
    })
}

fn parse_adb_devices(stdout: &str) -> Vec<MobileDevice> {
    stdout
        .lines()
        .filter_map(|line| {
            let line = line.trim();
            if line.is_empty() || line.starts_with("List of devices") {
                return None;
            }
            let mut parts = line.split_whitespace();
            let serial = parts.next()?.to_string();
            let state = parts.next()?.to_string();
            let attrs = parts
                .filter_map(|part| {
                    let (k, v) = part.split_once(':')?;
                    Some((k.to_string(), v.to_string()))
                })
                .collect();
            Some(MobileDevice {
                serial,
                state,
                attrs,
            })
        })
        .collect()
}

fn mobile_device_json(device: &MobileDevice, android_version: Option<String>) -> Value {
    let mut obj = Map::new();
    obj.insert("serial".into(), json!(device.serial));
    obj.insert("state".into(), json!(device.state));
    for (k, v) in &device.attrs {
        obj.insert(k.clone(), json!(v));
    }
    if let Some(version) = android_version.filter(|s| !s.is_empty()) {
        obj.insert("android_version".into(), json!(version));
    }
    Value::Object(obj)
}

async fn mobile_online_devices(timeout_ms: u64) -> std::result::Result<Vec<MobileDevice>, String> {
    let out = run_adb_command(None, &adb_args(&["devices", "-l"]), timeout_ms).await?;
    if !out.ok() {
        return Err(format!("adb devices failed: {}", out.stderr.trim()));
    }
    Ok(parse_adb_devices(&out.stdout)
        .into_iter()
        .filter(|d| d.state == "device")
        .collect())
}

async fn resolve_mobile_serial(
    args: &Value,
    timeout_ms: u64,
) -> std::result::Result<String, String> {
    if let Some(serial) = args
        .get("serial")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
    {
        return Ok(serial.to_string());
    }
    let devices = mobile_online_devices(timeout_ms).await?;
    match devices.len() {
        0 => Err("no online ADB devices found".to_string()),
        1 => Ok(devices[0].serial.clone()),
        _ => Err(format!(
            "multiple online devices found; pass serial (available: {})",
            devices
                .iter()
                .map(|d| d.serial.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        )),
    }
}

async fn mobile_getprop(serial: &str, prop: &str, timeout_ms: u64) -> Option<String> {
    let args = vec!["shell".to_string(), "getprop".to_string(), prop.to_string()];
    let out = run_adb_command(Some(serial), &args, timeout_ms)
        .await
        .ok()?;
    if out.ok() {
        Some(out.stdout.trim().to_string())
    } else {
        None
    }
}

fn parse_focus_lines(stdout: &str) -> Vec<String> {
    stdout
        .lines()
        .map(str::trim)
        .filter(|line| {
            line.contains("mCurrentFocus")
                || line.contains("mFocusedApp")
                || line.contains("topResumedActivity")
        })
        .map(str::to_string)
        .collect()
}

fn focus_token_package(token: &str) -> Option<String> {
    let clean = token.trim_matches(|c: char| {
        c == '{' || c == '}' || c == ')' || c == '(' || c == ',' || c == ';'
    });
    let (pkg, _) = clean.split_once('/')?;
    if pkg.contains('.')
        && pkg
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '.')
    {
        Some(pkg.to_string())
    } else {
        None
    }
}

fn parse_foreground_package(focus_lines: &[String]) -> Option<String> {
    for line in focus_lines {
        for token in line.split_whitespace() {
            if let Some(pkg) = focus_token_package(token) {
                return Some(pkg);
            }
        }
    }
    None
}

fn summarize_mobile_logcat(stdout: &str, package: Option<&str>) -> Value {
    let mut fatal_count = 0usize;
    let mut error_count = 0usize;
    let mut warning_count = 0usize;
    let mut surface_line_count = 0usize;
    let mut package_mentions = 0usize;
    let mut markers = Vec::new();
    let mut push_marker = |kind: &str, line: &str| {
        if markers.len() >= 30 {
            return;
        }
        let (text, truncated, total_chars) = truncate_chars(line, 500);
        markers.push(json!({
            "kind": kind,
            "line": text,
            "truncated": truncated,
            "total_chars": total_chars,
        }));
    };

    for line in stdout.lines() {
        let lower = line.to_ascii_lowercase();
        let package_hit = package.map(|pkg| line.contains(pkg)).unwrap_or(false);
        if package_hit {
            package_mentions += 1;
        }

        let is_fatal = line.contains("FATAL EXCEPTION")
            || lower.contains("fatal signal")
            || lower.contains("androidruntime")
            || lower.contains(" anr ")
            || lower.contains(" crash");
        let is_error = is_fatal
            || line.contains(" E ")
            || line.contains(" E/")
            || (lower.contains("exception") && (line.contains(" E ") || package_hit));
        let is_warning = line.contains(" W ") || line.contains(" W/");
        let is_surface = lower.contains("surfaceview")
            || lower.contains("surfaceflinger")
            || lower.contains("choreographer")
            || lower.contains("fps")
            || lower.contains("godot");

        if is_fatal {
            fatal_count += 1;
            push_marker("fatal", line);
        } else if is_error {
            error_count += 1;
            push_marker("error", line);
        } else if is_warning {
            warning_count += 1;
        }
        if is_surface {
            surface_line_count += 1;
        }
    }

    json!({
        "line_count": stdout.lines().count(),
        "fatal_count": fatal_count,
        "error_count": error_count,
        "warning_count": warning_count,
        "surface_line_count": surface_line_count,
        "package_mentions": package_mentions,
        "has_crash_markers": fatal_count > 0,
        "markers": markers,
    })
}

fn parse_mobile_bounds(raw: &str) -> Option<MobileBounds> {
    let nums: Vec<i64> = raw
        .split(|c| matches!(c, '[' | ']' | ','))
        .filter(|s| !s.trim().is_empty())
        .filter_map(|s| s.trim().parse::<i64>().ok())
        .collect();
    if nums.len() == 4 {
        Some(MobileBounds {
            left: nums[0],
            top: nums[1],
            right: nums[2],
            bottom: nums[3],
        })
    } else {
        None
    }
}

fn attr_bool(attrs: &HashMap<String, String>, key: &str) -> bool {
    attrs.get(key).map(|v| v == "true").unwrap_or(false)
}

fn decode_xml_attr_value(raw: &str) -> String {
    raw.replace("&quot;", "\"")
        .replace("&apos;", "'")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&amp;", "&")
}

fn parse_xml_attrs(tag_body: &str) -> HashMap<String, String> {
    let mut attrs = HashMap::new();
    let bytes = tag_body.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        while i < bytes.len() && (bytes[i].is_ascii_whitespace() || bytes[i] == b'/') {
            i += 1;
        }
        let key_start = i;
        while i < bytes.len()
            && !bytes[i].is_ascii_whitespace()
            && bytes[i] != b'='
            && bytes[i] != b'/'
        {
            i += 1;
        }
        if key_start == i {
            i += 1;
            continue;
        }
        let key = &tag_body[key_start..i];
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= bytes.len() || bytes[i] != b'=' {
            continue;
        }
        i += 1;
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= bytes.len() || (bytes[i] != b'"' && bytes[i] != b'\'') {
            continue;
        }
        let quote = bytes[i];
        i += 1;
        let value_start = i;
        while i < bytes.len() && bytes[i] != quote {
            i += 1;
        }
        if i > bytes.len() {
            break;
        }
        let value = decode_xml_attr_value(&tag_body[value_start..i]);
        attrs.insert(key.to_string(), value);
        i += 1;
    }
    attrs
}

fn node_from_attrs(ordinal: usize, attrs: HashMap<String, String>) -> MobileUiNode {
    let bounds = attrs.get("bounds").and_then(|s| parse_mobile_bounds(s));
    MobileUiNode {
        ordinal,
        index: attrs.get("index").cloned().unwrap_or_default(),
        text: attrs.get("text").cloned().unwrap_or_default(),
        resource_id: attrs.get("resource-id").cloned().unwrap_or_default(),
        class_name: attrs.get("class").cloned().unwrap_or_default(),
        package_name: attrs.get("package").cloned().unwrap_or_default(),
        content_desc: attrs.get("content-desc").cloned().unwrap_or_default(),
        clickable: attr_bool(&attrs, "clickable"),
        enabled: attrs.get("enabled").map(|v| v == "true").unwrap_or(true),
        focusable: attr_bool(&attrs, "focusable"),
        focused: attr_bool(&attrs, "focused"),
        scrollable: attr_bool(&attrs, "scrollable"),
        bounds,
    }
}

fn parse_uiautomator_nodes(xml: &str) -> std::result::Result<Vec<MobileUiNode>, String> {
    let mut nodes = Vec::new();
    let mut search_start = 0usize;
    while let Some(rel) = xml[search_start..].find("<node") {
        let tag_start = search_start + rel;
        let after_name = tag_start + "<node".len();
        let next = xml[after_name..].chars().next();
        if !matches!(next, Some(c) if c.is_ascii_whitespace() || c == '/' || c == '>') {
            search_start = after_name;
            continue;
        }
        let Some(tag_end_rel) = xml[tag_start..].find('>') else {
            return Err("unterminated <node> tag in UI XML".to_string());
        };
        let tag_end = tag_start + tag_end_rel;
        let tag_body = &xml[after_name..tag_end];
        let attrs = parse_xml_attrs(tag_body);
        let ordinal = nodes.len();
        nodes.push(node_from_attrs(ordinal, attrs));
        search_start = tag_end + 1;
    }
    Ok(nodes)
}

async fn mobile_dump_ui_xml(
    serial: &str,
    timeout_ms: u64,
) -> std::result::Result<(AdbCommandOutput, AdbCommandOutput), String> {
    let dump_args = vec![
        "shell".to_string(),
        "uiautomator".to_string(),
        "dump".to_string(),
        MOBILE_UI_DUMP_PATH.to_string(),
    ];
    let dump = run_adb_command(Some(serial), &dump_args, timeout_ms).await?;
    if !dump.ok() {
        return Err(format!("uiautomator dump failed: {}", dump.stderr.trim()));
    }
    let cat_args = vec![
        "exec-out".to_string(),
        "cat".to_string(),
        MOBILE_UI_DUMP_PATH.to_string(),
    ];
    let cat = run_adb_command(Some(serial), &cat_args, timeout_ms).await?;
    if !cat.ok() {
        return Err(format!("read UI XML failed: {}", cat.stderr.trim()));
    }
    Ok((dump, cat))
}

fn sanitize_mobile_path_component(s: &str) -> String {
    let sanitized: String = s
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '-' || c == '_' {
                c
            } else {
                '-'
            }
        })
        .collect();
    if sanitized.is_empty() {
        "device".to_string()
    } else {
        sanitized
    }
}

fn mobile_screenshot_path(args: &Value, serial: &str) -> PathBuf {
    if let Some(path) = args
        .get("path")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
    {
        return PathBuf::from(path);
    }
    let ts = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    std::env::temp_dir().join(format!(
        "agent-bridge-mobile-screenshot-{}-{ts}.png",
        sanitize_mobile_path_component(serial)
    ))
}

fn adb_input_text_arg(text: &str) -> String {
    text.replace(' ', "%s")
}

macro_rules! mobile_tool_struct {
    ($name:ident) => {
        pub struct $name {
            hub: Hub,
        }
        impl $name {
            pub fn new(hub: Hub) -> Self {
                Self { hub }
            }
        }
    };
}

mobile_tool_struct!(MobileListDevicesTool);
#[async_trait]
impl McpTool for MobileListDevicesTool {
    fn name(&self) -> &'static str {
        "mobile_list_devices"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List Android devices visible to ADB. Returns serials, connection \
                 state, `adb devices -l` attributes, and optional Android version/model \
                 properties. Use before any mobile_* action when multiple devices may be \
                 connected."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "include_props": { "type": "boolean", "default": true, "description": "Read model and Android version via getprop for online devices." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let include_props = args
            .get("include_props")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let out = match run_adb_command(None, &adb_args(&["devices", "-l"]), timeout_ms).await {
            Ok(out) => out,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        if !out.ok() {
            return Ok(ToolResult::json_text(&json!({
                "status": "error",
                "adb": out.as_json(),
            })));
        }
        let devices = parse_adb_devices(&out.stdout);
        let mut rows = Vec::new();
        for device in &devices {
            let android_version = if include_props && device.state == "device" {
                mobile_getprop(&device.serial, "ro.build.version.release", timeout_ms).await
            } else {
                None
            };
            rows.push(mobile_device_json(device, android_version));
        }
        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "adb_bin": resolve_adb_bin(),
            "count": rows.len(),
            "devices": rows,
        })))
    }
}

mobile_tool_struct!(MobileCurrentFocusTool);
#[async_trait]
impl McpTool for MobileCurrentFocusTool {
    fn name(&self) -> &'static str {
        "mobile_current_focus"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read the current Android foreground window/activity via `dumpsys \
                 window`, without taking a screenshot."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "serial": mobile_schema_serial(),
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let serial = match resolve_mobile_serial(&args, timeout_ms).await {
            Ok(s) => s,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let out = match run_adb_command(
            Some(&serial),
            &adb_args(&["shell", "dumpsys", "window"]),
            timeout_ms,
        )
        .await
        {
            Ok(out) => out,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        if !out.ok() {
            return Ok(ToolResult::json_text(&json!({
                "status": "error",
                "serial": serial,
                "adb": out.as_json(),
            })));
        }
        let focus_lines = parse_focus_lines(&out.stdout);
        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "serial": serial,
            "focus_lines": focus_lines,
            "duration_ms": out.duration_ms,
        })))
    }
}

mobile_tool_struct!(MobileScreenshotTool);
#[async_trait]
impl McpTool for MobileScreenshotTool {
    fn name(&self) -> &'static str {
        "mobile_screenshot"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Capture an Android device screenshot through `adb exec-out screencap \
                 -p`. Returns a saved PNG path by default, or an inline image block when \
                 `inline=true`."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "serial": mobile_schema_serial(),
                    "path": { "type": "string", "description": "Optional local output path. Defaults to a PNG under the system temp directory when inline=false." },
                    "inline": { "type": "boolean", "default": false, "description": "Return the PNG as an MCP image block instead of only saving it to disk." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let serial = match resolve_mobile_serial(&args, timeout_ms).await {
            Ok(s) => s,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let out = match run_adb_binary_command(
            Some(&serial),
            &adb_args(&["exec-out", "screencap", "-p"]),
            timeout_ms,
        )
        .await
        {
            Ok(out) => out,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        if !out.ok() {
            return Ok(ToolResult::json_text(&json!({
                "status": "error",
                "serial": serial,
                "adb": out.as_json(),
            })));
        }
        const PNG_SIGNATURE: &[u8] = &[137, 80, 78, 71, 13, 10, 26, 10];
        if !out.stdout.starts_with(PNG_SIGNATURE) {
            return Ok(ToolResult::json_text(&json!({
                "status": "error",
                "serial": serial,
                "error": "screencap output did not start with a PNG signature",
                "adb": out.as_json(),
            })));
        }

        let inline = args
            .get("inline")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let explicit_path = args
            .get("path")
            .and_then(|v| v.as_str())
            .filter(|s| !s.trim().is_empty())
            .is_some();
        let should_write = explicit_path || !inline;
        let mut path_value = Value::Null;
        if should_write {
            let path = mobile_screenshot_path(&args, &serial);
            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() && !parent.exists() {
                    return Ok(ToolResult::error(format!(
                        "screenshot parent directory does not exist: {}",
                        parent.to_string_lossy()
                    )));
                }
            }
            if let Err(e) = std::fs::write(&path, &out.stdout) {
                return Ok(ToolResult::error(format!("write screenshot failed: {e}")));
            }
            path_value = json!(path.to_string_lossy());
        }

        let meta = json!({
            "status": "ok",
            "serial": serial,
            "mime_type": "image/png",
            "bytes": out.stdout.len(),
            "path": path_value,
            "duration_ms": out.duration_ms,
        });
        if inline {
            let b64 = general_purpose::STANDARD.encode(&out.stdout);
            return Ok(ToolResult {
                content: vec![
                    ContentBlock::image(b64, "image/png"),
                    ContentBlock::text(
                        serde_json::to_string_pretty(&meta).unwrap_or_else(|_| meta.to_string()),
                    ),
                ],
                is_error: false,
                backend_id: None,
            });
        }
        Ok(ToolResult::json_text(&meta))
    }
}

mobile_tool_struct!(MobileHealthTool);
#[async_trait]
impl McpTool for MobileHealthTool {
    fn name(&self) -> &'static str {
        "mobile_health"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Collect a compact Android device/app health snapshot: foreground \
                 package, focus lines, recent crash/error logcat markers, and optional \
                 UIAutomator canvas/semantic-node analysis."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "serial": mobile_schema_serial(),
                    "package": { "type": "string", "description": "Optional expected foreground Android package." },
                    "log_lines": { "type": "integer", "minimum": 1, "maximum": 5000, "default": 200 },
                    "include_ui": { "type": "boolean", "default": true },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let serial = match resolve_mobile_serial(&args, timeout_ms).await {
            Ok(s) => s,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let expected_package = args
            .get("package")
            .and_then(|v| v.as_str())
            .filter(|s| !s.trim().is_empty());
        let log_lines = args
            .get("log_lines")
            .and_then(|v| v.as_u64())
            .unwrap_or(200)
            .clamp(1, 5000)
            .to_string();
        let include_ui = args
            .get("include_ui")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);

        let mut partial = false;
        let focus_out = run_adb_command(
            Some(&serial),
            &adb_args(&["shell", "dumpsys", "window"]),
            timeout_ms,
        )
        .await;
        let (focus_lines, focus_status) = match focus_out {
            Ok(out) if out.ok() => {
                let lines = parse_focus_lines(&out.stdout);
                (
                    lines,
                    json!({ "status": "ok", "duration_ms": out.duration_ms }),
                )
            }
            Ok(out) => {
                partial = true;
                (
                    Vec::new(),
                    json!({ "status": "error", "adb": out.as_json() }),
                )
            }
            Err(e) => {
                partial = true;
                (Vec::new(), json!({ "status": "error", "error": e }))
            }
        };
        let foreground_package = parse_foreground_package(&focus_lines);
        let log_package = expected_package.or(foreground_package.as_deref());

        let log_out = run_adb_command(
            Some(&serial),
            &vec!["logcat".into(), "-d".into(), "-t".into(), log_lines.clone()],
            timeout_ms,
        )
        .await;
        let logcat = match log_out {
            Ok(out) if out.ok() => {
                let mut summary = summarize_mobile_logcat(&out.stdout, log_package);
                summary["status"] = json!("ok");
                summary["package"] = json!(log_package);
                summary["requested_lines"] = json!(log_lines);
                summary["duration_ms"] = json!(out.duration_ms);
                summary["truncated"] = json!(out.truncated);
                summary
            }
            Ok(out) => {
                partial = true;
                json!({ "status": "error", "adb": out.as_json() })
            }
            Err(e) => {
                partial = true;
                json!({ "status": "error", "error": e })
            }
        };

        let ui = if include_ui {
            match mobile_dump_ui_xml(&serial, timeout_ms).await {
                Ok((dump, cat)) => match parse_uiautomator_nodes(&cat.stdout) {
                    Ok(nodes) => json!({
                        "status": "ok",
                        "analysis": MobileUiAnalysis::from_nodes(&nodes).as_json(),
                        "dump": dump.as_json(),
                    }),
                    Err(e) => {
                        partial = true;
                        json!({ "status": "error", "error": e })
                    }
                },
                Err(e) => {
                    partial = true;
                    json!({ "status": "error", "error": e })
                }
            }
        } else {
            json!({ "status": "skipped" })
        };

        let package_match = match (expected_package, foreground_package.as_deref()) {
            (Some(expected), Some(actual)) => Some(expected == actual),
            (Some(_), None) => Some(false),
            (None, _) => None,
        };
        Ok(ToolResult::json_text(&json!({
            "status": if partial { "partial" } else { "ok" },
            "serial": serial,
            "expected_package": expected_package,
            "foreground_package": foreground_package,
            "package_match": package_match,
            "focus_lines": focus_lines,
            "focus": focus_status,
            "logcat": logcat,
            "ui": ui,
        })))
    }
}

mobile_tool_struct!(MobileUiSnapshotTool);
#[async_trait]
impl McpTool for MobileUiSnapshotTool {
    fn name(&self) -> &'static str {
        "mobile_ui_snapshot"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Run `uiautomator dump` and return a compact structured Android UI \
                 node summary. Optionally include truncated raw XML. Prefer this over \
                 screenshot reading when native Android controls are visible."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "serial": mobile_schema_serial(),
                    "max_nodes": { "type": "integer", "minimum": 1, "maximum": 500, "default": 100 },
                    "include_xml": { "type": "boolean", "default": false },
                    "xml_max_chars": { "type": "integer", "minimum": 0, "maximum": 200000, "default": 20000 },
                    "selector": mobile_schema_selector(),
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let serial = match resolve_mobile_serial(&args, timeout_ms).await {
            Ok(s) => s,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let (dump, cat) = match mobile_dump_ui_xml(&serial, timeout_ms).await {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let nodes = match parse_uiautomator_nodes(&cat.stdout) {
            Ok(nodes) => nodes,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let selector = match args.get("selector") {
            Some(v) => match MobileSelector::from_value(v) {
                Ok(s) => Some(s),
                Err(e) => return Ok(ToolResult::error(e)),
            },
            None => None,
        };
        let max_nodes = args
            .get("max_nodes")
            .and_then(|v| v.as_u64())
            .unwrap_or(100)
            .clamp(1, 500) as usize;
        let visible_nodes: Vec<Value> = nodes
            .iter()
            .filter(|n| selector.as_ref().map(|s| s.matches(n)).unwrap_or(true))
            .take(max_nodes)
            .map(MobileUiNode::compact_json)
            .collect();
        let analysis = MobileUiAnalysis::from_nodes(&nodes);
        let include_xml = args
            .get("include_xml")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let mut resp = json!({
            "status": "ok",
            "serial": serial,
            "node_count": nodes.len(),
            "returned_nodes": visible_nodes.len(),
            "analysis": analysis.as_json(),
            "nodes": visible_nodes,
            "dump": dump.as_json(),
        });
        if include_xml {
            let xml_max = args
                .get("xml_max_chars")
                .and_then(|v| v.as_u64())
                .unwrap_or(20_000)
                .min(200_000) as usize;
            let (xml, xml_truncated, xml_total_chars) = truncate_chars(&cat.stdout, xml_max);
            resp["xml"] = json!(xml);
            resp["xml_truncated"] = json!(xml_truncated);
            resp["xml_total_chars"] = json!(xml_total_chars);
        }
        Ok(ToolResult::json_text(&resp))
    }
}

mobile_tool_struct!(MobileLogcatTailTool);
#[async_trait]
impl McpTool for MobileLogcatTailTool {
    fn name(&self) -> &'static str {
        "mobile_logcat_tail"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Return recent Android logcat lines from a selected device. Optional \
                 substring filtering happens after capture so callers can quickly inspect app \
                 crashes or runtime warnings."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "serial": mobile_schema_serial(),
                    "lines": { "type": "integer", "minimum": 1, "maximum": 5000, "default": 200 },
                    "filter": { "type": "string", "description": "Optional substring filter applied to captured lines." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let serial = match resolve_mobile_serial(&args, timeout_ms).await {
            Ok(s) => s,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let lines = args
            .get("lines")
            .and_then(|v| v.as_u64())
            .unwrap_or(200)
            .clamp(1, 5000)
            .to_string();
        let out = match run_adb_command(
            Some(&serial),
            &vec!["logcat".into(), "-d".into(), "-t".into(), lines],
            timeout_ms,
        )
        .await
        {
            Ok(out) => out,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        if !out.ok() {
            return Ok(ToolResult::json_text(&json!({
                "status": "error",
                "serial": serial,
                "adb": out.as_json(),
            })));
        }
        let filter = args.get("filter").and_then(|v| v.as_str()).unwrap_or("");
        let rows: Vec<&str> = out
            .stdout
            .lines()
            .filter(|line| filter.is_empty() || line.contains(filter))
            .collect();
        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "serial": serial,
            "line_count": rows.len(),
            "filter": if filter.is_empty() { Value::Null } else { json!(filter) },
            "lines": rows,
            "duration_ms": out.duration_ms,
            "truncated": out.truncated,
        })))
    }
}

mobile_tool_struct!(MobileInstallApkTool);
#[async_trait]
impl McpTool for MobileInstallApkTool {
    fn name(&self) -> &'static str {
        "mobile_install_apk"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Install an APK on an Android device via ADB. This mutates the \
                 selected device and returns the raw install result."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "serial": mobile_schema_serial(),
                    "apk": { "type": "string", "description": "Absolute or daemon-cwd-relative path to the APK." },
                    "reinstall": { "type": "boolean", "default": true, "description": "Pass -r to adb install." },
                    "downgrade": { "type": "boolean", "default": false, "description": "Pass -d to adb install." },
                    "grant_permissions": { "type": "boolean", "default": false, "description": "Pass -g to adb install." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": 120000 }
                },
                "required": ["apk"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(120_000)
            .clamp(1_000, 120_000);
        let serial = match resolve_mobile_serial(&args, timeout_ms).await {
            Ok(s) => s,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let apk = match args.get("apk").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s,
            _ => return Ok(ToolResult::error("missing 'apk'")),
        };
        let apk_path = PathBuf::from(apk);
        if !apk_path.exists() {
            return Ok(ToolResult::error(format!("apk not found: {apk}")));
        }
        let mut cmd = vec!["install".to_string()];
        if args
            .get("reinstall")
            .and_then(|v| v.as_bool())
            .unwrap_or(true)
        {
            cmd.push("-r".to_string());
        }
        if args
            .get("downgrade")
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
        {
            cmd.push("-d".to_string());
        }
        if args
            .get("grant_permissions")
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
        {
            cmd.push("-g".to_string());
        }
        cmd.push(apk_path.to_string_lossy().into_owned());
        let out = match run_adb_command(Some(&serial), &cmd, timeout_ms).await {
            Ok(out) => out,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        Ok(ToolResult::json_text(&json!({
            "status": if out.ok() { "ok" } else { "error" },
            "serial": serial,
            "apk": apk,
            "adb": out.as_json(),
        })))
    }
}

mobile_tool_struct!(MobileLaunchAppTool);
#[async_trait]
impl McpTool for MobileLaunchAppTool {
    fn name(&self) -> &'static str {
        "mobile_launch_app"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Launch an Android app. Pass `component` for an exact activity, \
                 or pass `package` only to use the launcher category through `monkey`."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "serial": mobile_schema_serial(),
                    "package": { "type": "string", "description": "Android package name, e.g. com.example.app." },
                    "activity": { "type": "string", "description": "Optional activity class. Relative values starting with '.' are joined with package." },
                    "component": { "type": "string", "description": "Exact component, e.g. com.example/.MainActivity." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let serial = match resolve_mobile_serial(&args, timeout_ms).await {
            Ok(s) => s,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let package = args.get("package").and_then(|v| v.as_str()).unwrap_or("");
        let component_arg = args
            .get("component")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());
        let activity = args
            .get("activity")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty());
        let cmd = if let Some(component) = component_arg {
            vec![
                "shell".to_string(),
                "am".to_string(),
                "start".to_string(),
                "-n".to_string(),
                component.to_string(),
            ]
        } else if let Some(activity) = activity {
            if package.is_empty() {
                return Ok(ToolResult::error(
                    "package is required when activity is provided without component",
                ));
            }
            let component = if activity.starts_with('.') {
                format!("{package}/{activity}")
            } else if activity.contains('/') {
                activity.to_string()
            } else {
                format!("{package}/{activity}")
            };
            vec![
                "shell".to_string(),
                "am".to_string(),
                "start".to_string(),
                "-n".to_string(),
                component,
            ]
        } else {
            if package.is_empty() {
                return Ok(ToolResult::error(
                    "missing 'package' or exact 'component' to launch",
                ));
            }
            vec![
                "shell".to_string(),
                "monkey".to_string(),
                "-p".to_string(),
                package.to_string(),
                "-c".to_string(),
                "android.intent.category.LAUNCHER".to_string(),
                "1".to_string(),
            ]
        };
        let out = match run_adb_command(Some(&serial), &cmd, timeout_ms).await {
            Ok(out) => out,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        Ok(ToolResult::json_text(&json!({
            "status": if out.ok() { "ok" } else { "error" },
            "serial": serial,
            "adb": out.as_json(),
        })))
    }
}

mobile_tool_struct!(MobileClickTool);
#[async_trait]
impl McpTool for MobileClickTool {
    fn name(&self) -> &'static str {
        "mobile_click"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Tap an Android device by coordinates, or resolve a UI Automator \
                 selector and tap the center of the selected node's bounds. This performs a \
                 real GUI tap through `adb shell input tap`."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "serial": mobile_schema_serial(),
                    "x": { "type": "integer", "description": "Tap X coordinate. Use with y." },
                    "y": { "type": "integer", "description": "Tap Y coordinate. Use with x." },
                    "selector": mobile_schema_selector(),
                    "match_index": { "type": "integer", "minimum": 0, "default": 0, "description": "When selector matches multiple nodes, choose this zero-based match." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let serial = match resolve_mobile_serial(&args, timeout_ms).await {
            Ok(s) => s,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let explicit_x = args.get("x").and_then(|v| v.as_i64());
        let explicit_y = args.get("y").and_then(|v| v.as_i64());
        let (x, y, selected_node) = match (explicit_x, explicit_y) {
            (Some(x), Some(y)) => (x, y, Value::Null),
            (Some(_), None) | (None, Some(_)) => {
                return Ok(ToolResult::error(
                    "both x and y are required for coordinate tap",
                ));
            }
            (None, None) => {
                let selector_value = match args.get("selector") {
                    Some(v) => v,
                    None => return Ok(ToolResult::error("pass coordinates or selector")),
                };
                let selector = match MobileSelector::from_value(selector_value) {
                    Ok(s) => s,
                    Err(e) => return Ok(ToolResult::error(e)),
                };
                let (_, cat) = match mobile_dump_ui_xml(&serial, timeout_ms).await {
                    Ok(v) => v,
                    Err(e) => return Ok(ToolResult::error(e)),
                };
                let nodes = match parse_uiautomator_nodes(&cat.stdout) {
                    Ok(nodes) => nodes,
                    Err(e) => return Ok(ToolResult::error(e)),
                };
                let matches: Vec<&MobileUiNode> =
                    nodes.iter().filter(|n| selector.matches(n)).collect();
                let match_index = args
                    .get("match_index")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(0) as usize;
                let Some(node) = matches.get(match_index).copied() else {
                    return Ok(ToolResult::error(format!(
                        "selector matched {} node(s), no match_index {match_index}",
                        matches.len()
                    )));
                };
                let Some(bounds) = node.bounds else {
                    return Ok(ToolResult::error("selected node has no bounds"));
                };
                let (x, y) = bounds.center();
                (x, y, node.compact_json())
            }
        };
        let cmd = vec![
            "shell".to_string(),
            "input".to_string(),
            "tap".to_string(),
            x.to_string(),
            y.to_string(),
        ];
        let out = match run_adb_command(Some(&serial), &cmd, timeout_ms).await {
            Ok(out) => out,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        Ok(ToolResult::json_text(&json!({
            "status": if out.ok() { "ok" } else { "error" },
            "serial": serial,
            "tap": { "x": x, "y": y },
            "selected_node": selected_node,
            "adb": out.as_json(),
        })))
    }
}

mobile_tool_struct!(MobileInputTextTool);
#[async_trait]
impl McpTool for MobileInputTextTool {
    fn name(&self) -> &'static str {
        "mobile_input_text"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Send text to the focused Android control via `adb shell input text`. \
                 Spaces are encoded as `%s`, matching Android input command conventions."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "serial": mobile_schema_serial(),
                    "text": { "type": "string", "description": "Text to send to the focused control." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                },
                "required": ["text"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let serial = match resolve_mobile_serial(&args, timeout_ms).await {
            Ok(s) => s,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let text = match args.get("text").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s,
            _ => return Ok(ToolResult::error("missing or empty 'text'")),
        };
        let encoded = adb_input_text_arg(text);
        let cmd = vec![
            "shell".to_string(),
            "input".to_string(),
            "text".to_string(),
            encoded.clone(),
        ];
        let out = match run_adb_command(Some(&serial), &cmd, timeout_ms).await {
            Ok(out) => out,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        Ok(ToolResult::json_text(&json!({
            "status": if out.ok() { "ok" } else { "error" },
            "serial": serial,
            "encoded_text": encoded,
            "adb": out.as_json(),
        })))
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct AppleUsbDevice {
    product_name: String,
    vendor_name: String,
    serial: String,
    udid: String,
    vendor_id: Option<u64>,
    product_id: Option<u64>,
    location_id: Option<u64>,
    supports_iphone_os: bool,
}

fn parse_ioreg_value(line: &str, key: &str) -> Option<String> {
    let prefix = format!("\"{key}\" = ");
    let value = line.split_once(&prefix)?.1.trim();
    if let Some(s) = value.strip_prefix('"') {
        return Some(s.split('"').next().unwrap_or_default().to_string());
    }
    Some(
        value
            .split_whitespace()
            .next()
            .unwrap_or_default()
            .trim_end_matches(',')
            .to_string(),
    )
}

fn parse_ioreg_bool(line: &str, key: &str) -> Option<bool> {
    parse_ioreg_value(line, key).and_then(|v| match v.as_str() {
        "Yes" | "true" | "1" => Some(true),
        "No" | "false" | "0" => Some(false),
        _ => None,
    })
}

fn parse_ioreg_u64(line: &str, key: &str) -> Option<u64> {
    parse_ioreg_value(line, key).and_then(|v| v.parse::<u64>().ok())
}

fn apple_usb_device_json(device: &AppleUsbDevice) -> Value {
    json!({
        "product_name": device.product_name,
        "vendor_name": device.vendor_name,
        "serial": device.serial,
        "udid": device.udid,
        "vendor_id": device.vendor_id,
        "product_id": device.product_id,
        "location_id": device.location_id,
        "supports_iphone_os": device.supports_iphone_os,
    })
}

fn parse_apple_usb_devices_from_ioreg(stdout: &str) -> Vec<AppleUsbDevice> {
    #[derive(Default)]
    struct Builder {
        in_device: bool,
        product_name: Option<String>,
        vendor_name: Option<String>,
        serial: Option<String>,
        udid: Option<String>,
        vendor_id: Option<u64>,
        product_id: Option<u64>,
        location_id: Option<u64>,
        supports_iphone_os: Option<bool>,
    }

    impl Builder {
        fn finish(&mut self, out: &mut Vec<AppleUsbDevice>) {
            if !self.in_device {
                return;
            }
            let product_name = self.product_name.take().unwrap_or_default();
            let vendor_name = self.vendor_name.take().unwrap_or_default();
            let serial = self.serial.take().unwrap_or_default();
            let udid = self.udid.take().unwrap_or_else(|| serial.clone());
            let supports_iphone_os = self.supports_iphone_os.unwrap_or(false);
            let is_apple_mobile =
                vendor_name == "Apple Inc." && (supports_iphone_os || product_name.contains("iP"));
            if is_apple_mobile {
                out.push(AppleUsbDevice {
                    product_name,
                    vendor_name,
                    serial,
                    udid,
                    vendor_id: self.vendor_id.take(),
                    product_id: self.product_id.take(),
                    location_id: self.location_id.take(),
                    supports_iphone_os,
                });
            }
            *self = Builder::default();
        }
    }

    let mut out = Vec::new();
    let mut current = Builder::default();
    for line in stdout.lines() {
        let starts_device = line.contains("+-o ")
            && line.contains("<class IOUSBHostDevice")
            && (line.contains("iPhone@") || line.contains("iPad@") || line.contains("iPod@"));
        let starts_other_device = line.contains("+-o ") && line.contains("<class IOUSBHostDevice");
        if starts_other_device && current.in_device {
            current.finish(&mut out);
        }
        if starts_device {
            current.in_device = true;
            if line.contains("iPhone@") {
                current.product_name = Some("iPhone".to_string());
            } else if line.contains("iPad@") {
                current.product_name = Some("iPad".to_string());
            } else if line.contains("iPod@") {
                current.product_name = Some("iPod".to_string());
            }
            continue;
        }
        if !current.in_device {
            continue;
        }
        if let Some(v) = parse_ioreg_value(line, "USB Product Name")
            .or_else(|| parse_ioreg_value(line, "kUSBProductString"))
        {
            current.product_name = Some(v);
        }
        if let Some(v) = parse_ioreg_value(line, "USB Vendor Name")
            .or_else(|| parse_ioreg_value(line, "kUSBVendorString"))
        {
            current.vendor_name = Some(v);
        }
        if let Some(v) = parse_ioreg_value(line, "USB Serial Number")
            .or_else(|| parse_ioreg_value(line, "kUSBSerialNumberString"))
        {
            current.serial = Some(v);
        }
        if let Some(v) = parse_ioreg_value(line, "UsbAppleDeviceUDID") {
            current.udid = Some(v);
        }
        if let Some(v) = parse_ioreg_u64(line, "idVendor") {
            current.vendor_id = Some(v);
        }
        if let Some(v) = parse_ioreg_u64(line, "idProduct") {
            current.product_id = Some(v);
        }
        if let Some(v) = parse_ioreg_u64(line, "locationID") {
            current.location_id = Some(v);
        }
        if let Some(v) = parse_ioreg_bool(line, "SupportsIPhoneOS") {
            current.supports_iphone_os = Some(v);
        }
    }
    current.finish(&mut out);
    out
}

async fn run_local_mobile_command(
    program: &str,
    args: &[&str],
    timeout_ms: u64,
) -> std::result::Result<AdbCommandOutput, String> {
    let started = Instant::now();
    let output = tokio::time::timeout(Duration::from_millis(timeout_ms), async {
        TokioCommand::new(program)
            .args(args)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .output()
            .await
    })
    .await;
    let duration_ms = started.elapsed().as_millis() as u64;
    let output = match output {
        Ok(Ok(output)) => output,
        Ok(Err(e)) => return Err(format!("spawn {program} failed: {e}")),
        Err(_) => {
            return Ok(AdbCommandOutput {
                exit_code: -1,
                stdout: String::new(),
                stderr: format!("killed after {timeout_ms} ms timeout"),
                duration_ms,
                truncated: false,
            });
        }
    };
    let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
    let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);
    Ok(AdbCommandOutput {
        exit_code: output.status.code().unwrap_or(-1),
        stdout,
        stderr,
        duration_ms,
        truncated: stdout_truncated || stderr_truncated,
    })
}

async fn command_path(program: &str, args: &[&str], timeout_ms: u64) -> Value {
    match run_local_mobile_command(program, args, timeout_ms).await {
        Ok(out) if out.ok() => {
            let path = out.stdout.lines().next().unwrap_or_default().trim();
            if path.is_empty() {
                json!({ "available": false, "path": Value::Null })
            } else {
                json!({ "available": true, "path": path })
            }
        }
        Ok(out) => json!({
            "available": false,
            "path": Value::Null,
            "error": out.stderr.trim(),
        }),
        Err(e) => json!({ "available": false, "path": Value::Null, "error": e }),
    }
}

async fn shell_command_path(tool: &str, timeout_ms: u64) -> Value {
    command_path("sh", &["-lc", &format!("command -v {tool}")], timeout_ms).await
}

mobile_tool_struct!(MobileAppleStatusTool);
#[async_trait]
impl McpTool for MobileAppleStatusTool {
    fn name(&self) -> &'static str {
        "mobile_apple_status"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only Apple mobile readiness probe. Reports Xcode/devicectl/simctl, \
                 optional third-party iOS tooling, and iPhone/iPad/iPod devices visible over USB. \
                 Use this before deciding whether to add or use iOS install/debug/UI automation."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "include_usb": { "type": "boolean", "default": true },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let include_usb = args
            .get("include_usb")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);

        let xcode_select = run_local_mobile_command("xcode-select", &["-p"], timeout_ms).await;
        let developer_dir = xcode_select
            .as_ref()
            .ok()
            .filter(|out| out.ok())
            .and_then(|out| out.stdout.lines().next())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string);
        let has_full_xcode = developer_dir
            .as_deref()
            .map(|p| {
                p.ends_with("/Xcode.app/Contents/Developer")
                    || p.contains(".app/Contents/Developer")
            })
            .unwrap_or(false);

        let devicectl = command_path("xcrun", &["--find", "devicectl"], timeout_ms).await;
        let simctl = command_path("xcrun", &["--find", "simctl"], timeout_ms).await;
        let xctrace = command_path("xcrun", &["--find", "xctrace"], timeout_ms).await;
        let xcdevice = command_path("xcrun", &["--find", "xcdevice"], timeout_ms).await;
        let third_party = json!({
            "cfgutil": shell_command_path("cfgutil", timeout_ms).await,
            "ios-deploy": shell_command_path("ios-deploy", timeout_ms).await,
            "idevice_id": shell_command_path("idevice_id", timeout_ms).await,
            "ideviceinfo": shell_command_path("ideviceinfo", timeout_ms).await,
            "idevicesyslog": shell_command_path("idevicesyslog", timeout_ms).await,
            "pymobiledevice3": shell_command_path("pymobiledevice3", timeout_ms).await,
            "tidevice": shell_command_path("tidevice", timeout_ms).await,
            "idb": shell_command_path("idb", timeout_ms).await,
            "idb_companion": shell_command_path("idb_companion", timeout_ms).await,
        });

        let usb_devices = if include_usb {
            match run_local_mobile_command("ioreg", &["-p", "IOUSB", "-l", "-w0"], timeout_ms).await
            {
                Ok(out) if out.ok() => parse_apple_usb_devices_from_ioreg(&out.stdout)
                    .iter()
                    .map(apple_usb_device_json)
                    .collect::<Vec<_>>(),
                _ => Vec::new(),
            }
        } else {
            Vec::new()
        };
        let has_usb_device = !usb_devices.is_empty();
        let devicectl_ready = devicectl
            .get("available")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let simctl_ready = simctl
            .get("available")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let libimobiledevice_ready = third_party
            .get("idevice_id")
            .and_then(|v| v.get("available"))
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let mut recommendations = Vec::new();
        if !has_full_xcode {
            recommendations.push(
                "Install/select full Xcode before expecting devicectl/simctl workflows."
                    .to_string(),
            );
        }
        if has_usb_device && !devicectl_ready && !libimobiledevice_ready {
            recommendations.push(
                "USB sees Apple mobile hardware, but no devicectl/libimobiledevice bridge is available."
                    .to_string(),
            );
        }
        if !has_usb_device {
            recommendations.push("No iPhone/iPad/iPod is visible over USB.".to_string());
        }

        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "xcode": {
                "developer_dir": developer_dir,
                "full_xcode_selected": has_full_xcode,
                "raw": xcode_select.map(|out| out.as_json()).unwrap_or_else(|e| json!({ "error": e })),
            },
            "apple_tools": {
                "devicectl": devicectl,
                "simctl": simctl,
                "xctrace": xctrace,
                "xcdevice": xcdevice,
            },
            "third_party_tools": third_party,
            "usb": {
                "checked": include_usb,
                "apple_mobile_count": usb_devices.len(),
                "devices": usb_devices,
            },
            "readiness": {
                "physical_usb_visible": has_usb_device,
                "physical_devicectl_ready": has_usb_device && devicectl_ready,
                "physical_libimobiledevice_ready": has_usb_device && libimobiledevice_ready,
                "simulator_ready": simctl_ready,
                "ui_automation_ready": false,
            },
            "recommendations": recommendations,
        })))
    }
}

fn mobile_schema_ios_udid() -> Value {
    json!({
        "type": "string",
        "description": "iOS device UDID. When omitted, the first `idevice_id -l` device is used."
    })
}

async fn ios_visible_udids(timeout_ms: u64) -> std::result::Result<Vec<String>, String> {
    let out = run_local_mobile_command("idevice_id", &["-l"], timeout_ms).await?;
    if !out.ok() {
        return Err(out.stderr.trim().to_string());
    }
    Ok(out
        .stdout
        .lines()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
        .collect())
}

async fn ios_selected_udid(args: &Value, timeout_ms: u64) -> std::result::Result<String, String> {
    if let Some(udid) = args
        .get("udid")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        return Ok(udid.to_string());
    }
    ios_visible_udids(timeout_ms)
        .await?
        .into_iter()
        .next()
        .ok_or_else(|| "no iOS device visible via idevice_id".to_string())
}

async fn ios_info_key(udid: &str, key: &str, timeout_ms: u64) -> Option<String> {
    run_local_mobile_command("ideviceinfo", &["-u", udid, "-k", key], timeout_ms)
        .await
        .ok()
        .filter(|out| out.ok())
        .map(|out| out.stdout.trim().to_string())
        .filter(|s| !s.is_empty())
}

async fn ios_device_info_json(udid: &str, timeout_ms: u64) -> Value {
    let keys = [
        ("device_name", "DeviceName"),
        ("product_type", "ProductType"),
        ("product_version", "ProductVersion"),
        ("build_version", "BuildVersion"),
        ("serial_number", "SerialNumber"),
        ("cpu_architecture", "CPUArchitecture"),
        ("trusted_host_attached", "TrustedHostAttached"),
    ];
    let mut obj = Map::new();
    obj.insert("udid".into(), json!(udid));
    for (field, key) in keys {
        if let Some(value) = ios_info_key(udid, key, timeout_ms).await {
            obj.insert(field.into(), json!(value));
        }
    }
    Value::Object(obj)
}

fn parse_ios_installer_csv(stdout: &str, limit: usize) -> Vec<Value> {
    let mut records = Vec::new();
    let mut record = Vec::new();
    let mut field = String::new();
    let mut in_quotes = false;
    let mut chars = stdout.chars().peekable();
    while let Some(ch) = chars.next() {
        match ch {
            '"' if in_quotes && chars.peek() == Some(&'"') => {
                field.push('"');
                chars.next();
            }
            '"' => in_quotes = !in_quotes,
            ',' if !in_quotes => {
                record.push(field.trim().to_string());
                field.clear();
            }
            '\n' | '\r' if !in_quotes => {
                if ch == '\r' && chars.peek() == Some(&'\n') {
                    chars.next();
                }
                record.push(field.trim().to_string());
                field.clear();
                if !record.iter().all(|s| s.is_empty()) {
                    records.push(std::mem::take(&mut record));
                } else {
                    record.clear();
                }
            }
            _ => field.push(ch),
        }
    }
    if !field.is_empty() || !record.is_empty() {
        record.push(field.trim().to_string());
        if !record.iter().all(|s| s.is_empty()) {
            records.push(record);
        }
    }

    records
        .into_iter()
        .skip(1)
        .filter(|row| row.len() >= 3 && !row[0].is_empty())
        .take(limit)
        .map(|row| {
            json!({
                "bundle_identifier": row[0],
                "version": if row[1].is_empty() { Value::Null } else { json!(row[1]) },
                "display_name": row[2],
            })
        })
        .collect()
}

mobile_tool_struct!(MobileIosListDevicesTool);
#[async_trait]
impl McpTool for MobileIosListDevicesTool {
    fn name(&self) -> &'static str {
        "mobile_ios_list_devices"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List iPhone/iPad/iPod devices visible through libimobiledevice. \
                 Returns UDIDs and optional lockdownd device info such as model, iOS version, \
                 serial, and trust state."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "include_info": { "type": "boolean", "default": true },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let include_info = args
            .get("include_info")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let udids = match ios_visible_udids(timeout_ms).await {
            Ok(udids) => udids,
            Err(e) => {
                return Ok(ToolResult::json_text(&json!({
                    "status": "error",
                    "error": e,
                    "hint": "Install libimobiledevice and trust this computer on the device.",
                })));
            }
        };
        let mut devices = Vec::new();
        for udid in &udids {
            if include_info {
                devices.push(ios_device_info_json(udid, timeout_ms).await);
            } else {
                devices.push(json!({ "udid": udid }));
            }
        }
        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "count": devices.len(),
            "devices": devices,
        })))
    }
}

mobile_tool_struct!(MobileIosAppsTool);
#[async_trait]
impl McpTool for MobileIosAppsTool {
    fn name(&self) -> &'static str {
        "mobile_ios_apps"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List installed iOS apps through ideviceinstaller. Returns a compact \
                 parsed app list with bundle identifiers, display names, and versions."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "udid": mobile_schema_ios_udid(),
                    "scope": { "type": "string", "enum": ["user", "system", "all"], "default": "user" },
                    "limit": { "type": "integer", "minimum": 1, "maximum": 500, "default": 100 },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let udid = match ios_selected_udid(&args, timeout_ms).await {
            Ok(udid) => udid,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let scope = args
            .get("scope")
            .and_then(|v| v.as_str())
            .filter(|s| matches!(*s, "user" | "system" | "all"))
            .unwrap_or("user");
        let scope_arg = format!("--{scope}");
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(100)
            .clamp(1, 500) as usize;
        let out = match run_local_mobile_command(
            "ideviceinstaller",
            &["-u", &udid, "list", &scope_arg],
            timeout_ms,
        )
        .await
        {
            Ok(out) => out,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        if !out.ok() {
            return Ok(ToolResult::json_text(&json!({
                "status": "error",
                "udid": udid,
                "scope": scope,
                "ideviceinstaller": out.as_json(),
            })));
        }
        let apps = parse_ios_installer_csv(&out.stdout, limit);
        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "udid": udid,
            "scope": scope,
            "count": apps.len(),
            "limit": limit,
            "apps": apps,
            "truncated": out.truncated,
        })))
    }
}

mobile_tool_struct!(MobileIosSyslogTailTool);
#[async_trait]
impl McpTool for MobileIosSyslogTailTool {
    fn name(&self) -> &'static str {
        "mobile_ios_syslog_tail"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Capture a short iOS syslog sample through idevicesyslog. Use this for \
                 crash/runtime diagnostics before falling back to screenshots."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "udid": mobile_schema_ios_udid(),
                    "duration_ms": { "type": "integer", "minimum": 1000, "maximum": 15000, "default": 3000 },
                    "lines": { "type": "integer", "minimum": 1, "maximum": 500, "default": 100 },
                    "filter": { "type": "string", "description": "Optional substring filter applied after capture." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 120000, "default": MOBILE_DEFAULT_TIMEOUT_MS }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let timeout_ms = mobile_timeout_ms(&args);
        let udid = match ios_selected_udid(&args, timeout_ms).await {
            Ok(udid) => udid,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let duration_ms = args
            .get("duration_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(3_000)
            .clamp(1_000, 15_000);
        let duration_secs = ((duration_ms + 999) / 1000).to_string();
        let line_limit = args
            .get("lines")
            .and_then(|v| v.as_u64())
            .unwrap_or(100)
            .clamp(1, 500) as usize;
        let filter = args
            .get("filter")
            .and_then(|v| v.as_str())
            .map(str::to_string)
            .filter(|s| !s.is_empty());
        let command_timeout = timeout_ms.max(duration_ms + 2_000);
        let out = match run_local_mobile_command(
            "perl",
            &[
                "-e",
                "alarm shift; exec @ARGV",
                &duration_secs,
                "idevicesyslog",
                "-u",
                &udid,
            ],
            command_timeout,
        )
        .await
        {
            Ok(out) => out,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let mut matched = 0usize;
        let mut kept = Vec::new();
        for line in out.stdout.lines() {
            if filter.as_ref().is_some_and(|needle| !line.contains(needle)) {
                continue;
            }
            matched += 1;
            if kept.len() < line_limit {
                kept.push(line.to_string());
            }
        }
        Ok(ToolResult::json_text(&json!({
            "status": if matched > 0 || out.ok() { "ok" } else { "error" },
            "udid": udid,
            "duration_ms": duration_ms,
            "line_count": matched,
            "returned_lines": kept.len(),
            "filter": filter,
            "lines": kept,
            "idevicesyslog": {
                "exit_code": out.exit_code,
                "stderr": out.stderr,
                "duration_ms": out.duration_ms,
                "truncated": out.truncated,
            },
        })))
    }
}

