pub struct AgentSessionListTool {
    hub: Hub,
}
impl AgentSessionListTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for AgentSessionListTool {
    fn name(&self) -> &'static str {
        "agent_session_list"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List recent agent sessions (default 20, max 1000). Row: id, \
                 runtime, cwd, started_at, ended_at, exit_code. Filters: runtime_id, \
                 cwd_prefix, state, exit_code (negative=signal). Running rows carry \
                 liveness. Use agent_session_get(id) for full output."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "limit":      { "type": "integer", "minimum": 1, "maximum": 1000, "default": 20 },
                    "runtime_id": { "type": "string",  "description": "e.g. 'claude-code'" },
                    "cwd_prefix": { "type": "string",  "description": "Prefix-match the working dir." },
                    "state":      { "type": "string",  "enum": ["running","finished"] },
                    "exit_code":  { "type": "integer", "description": "Exact exit code (negative = signal)." }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(20)
            .min(1000) as u32;
        let filter = SessionFilter {
            runtime_id: args
                .get("runtime_id")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            cwd_prefix: args
                .get("cwd_prefix")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            exited_only: args
                .get("state")
                .and_then(|v| v.as_str())
                .and_then(|s| match s {
                    "finished" => Some(true),
                    "running" => Some(false),
                    _ => None,
                }),
            exit_code: args
                .get("exit_code")
                .and_then(|v| v.as_i64())
                .map(|n| n as i32),
        };
        let rows = store.list_sessions(&filter, limit).await?;
        // Strip stdout/stderr to keep the listing compact.
        let summary: Vec<Value> = rows
            .into_iter()
            .map(|s| {
                let running = s.ended_at.is_none();
                let mut row = json!({
                    "id":          s.id.as_str(),
                    "runtime_id":  s.runtime_id,
                    "cwd":         s.cwd,
                    "started_at":  s.started_at,
                    "ended_at":    s.ended_at,
                    "exit_code":   s.exit_code,
                    "running":     running,
                    "stdout_len":  s.stdout.as_ref().map(|x| x.len()).unwrap_or(0),
                    "stderr_len":  s.stderr.as_ref().map(|x| x.len()).unwrap_or(0),
                });
                if running {
                    let (pid, liveness) =
                        match self.hub.agent.as_ref().and_then(|a| a.pid_for(&s.id)) {
                            Some(pid) => {
                                let alive = std::path::Path::new(&format!("/proc/{pid}")).exists();
                                (Some(pid), if alive { "alive" } else { "dead" })
                            }
                            None => (None, "unknown"),
                        };
                    if let Some(p) = pid {
                        row["pid"] = json!(p);
                    }
                    row["liveness"] = json!(liveness);
                }
                row
            })
            .collect();
        Ok(ToolResult::json_text(&Value::Array(summary)))
    }
}

pub struct AgentSessionReconcileTool {
    hub: Hub,
}
impl AgentSessionReconcileTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for AgentSessionReconcileTool {
    fn name(&self) -> &'static str {
        "agent_session_reconcile"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Find stale running local agent sessions whose owning MCP process has \
                 likely disappeared, and optionally finalise them. Defaults to dry-run. Use \
                 this after MCP/IDE restarts when agent_session_list shows old running rows \
                 with no live child PID."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "dry_run": {
                        "type": "boolean",
                        "default": true,
                        "description": "When true, report candidates without mutating sessions."
                    },
                    "apply_confirmation": {
                        "type": "string",
                        "description": "Required exact value 'finalise_stale_sessions' when dry_run=false, after reviewing dry-run candidates."
                    },
                    "stale_after_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 604800,
                        "default": 300,
                        "description": "Only reconcile running sessions older than this age."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 1000,
                        "default": 100
                    },
                    "runtime_id": {
                        "type": "string",
                        "description": "Optional runtime filter, e.g. kilo or codex."
                    },
                    "cwd_prefix": {
                        "type": "string",
                        "description": "Optional cwd prefix filter."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        if !dry_run
            && args.get("apply_confirmation").and_then(|v| v.as_str())
                != Some("finalise_stale_sessions")
        {
            return Ok(ToolResult::error(
                "dry_run=false requires apply_confirmation=\"finalise_stale_sessions\" \
                 after reviewing dry-run candidates",
            ));
        }
        let stale_after_secs = args
            .get("stale_after_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(300)
            .clamp(60, 604_800);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(100)
            .min(1000) as u32;
        let filter = SessionFilter {
            runtime_id: args
                .get("runtime_id")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            cwd_prefix: args
                .get("cwd_prefix")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            exited_only: Some(false),
            exit_code: None,
        };
        let rows = store.list_sessions(&filter, limit).await?;
        let now = dispatch_now_secs();
        let mut candidates = Vec::new();
        let mut finalised_count = 0usize;
        let mut skipped_recent = 0usize;
        let mut skipped_unsupported_runtime = 0usize;
        let mut skipped_alive = 0usize;
        let mut errors = Vec::new();

        for session in rows {
            let age_secs = now.saturating_sub(session.started_at);
            if age_secs < stale_after_secs {
                skipped_recent += 1;
                continue;
            }
            if !is_local_process_agent_runtime(&session.runtime_id) {
                skipped_unsupported_runtime += 1;
                continue;
            }
            let (pid, liveness) = agent_session_liveness(&self.hub, &session);
            if liveness == "alive" {
                skipped_alive += 1;
                continue;
            }
            let reason = format!(
                "agent_session_reconcile: finalised stale running session after {age_secs}s; \
                 liveness={liveness}"
            );
            candidates.push(json!({
                "id": session.id.as_str(),
                "runtime_id": session.runtime_id.as_str(),
                "cwd": session.cwd.as_str(),
                "started_at": session.started_at,
                "age_secs": age_secs,
                "pid": pid,
                "liveness": liveness,
                "exit_code_if_applied": -15,
            }));
            if !dry_run {
                let stderr = append_reconcile_reason(session.stderr.as_deref(), &reason);
                match store
                    .finalise_session(
                        &session.id,
                        now,
                        Some(-15),
                        session.stdout.clone(),
                        Some(stderr),
                    )
                    .await
                {
                    Ok(()) => finalised_count += 1,
                    Err(e) => errors.push(json!({
                        "id": session.id.as_str(),
                        "error": e.to_string(),
                    })),
                }
            }
        }

        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "stale_after_secs": stale_after_secs,
            "scanned_count": skipped_recent
                + skipped_unsupported_runtime
                + skipped_alive
                + candidates.len(),
            "candidate_count": candidates.len(),
            "finalised_count": finalised_count,
            "skipped_recent": skipped_recent,
            "skipped_unsupported_runtime": skipped_unsupported_runtime,
            "skipped_alive": skipped_alive,
            "errors": errors,
            "candidates": candidates,
        })))
    }
}

fn append_reconcile_reason(existing: Option<&str>, reason: &str) -> String {
    match existing {
        Some(prev) if !prev.trim().is_empty() => format!("{prev}\n{reason}"),
        _ => reason.to_string(),
    }
}

fn is_local_process_agent_runtime(runtime_id: &str) -> bool {
    matches!(
        runtime_id,
        "claude-code" | "codex" | "kilo" | "opencode" | "gemini" | "auggie"
    )
}

fn agent_session_liveness(hub: &Hub, session: &StoredSession) -> (Option<u32>, &'static str) {
    let pid = hub
        .agents
        .get(&session.runtime_id)
        .and_then(|agent| agent.pid_for(&session.id))
        .or_else(|| {
            hub.agent
                .as_ref()
                .filter(|agent| agent.id() == session.runtime_id)
                .and_then(|agent| agent.pid_for(&session.id))
        });
    match pid {
        Some(pid) if process_pid_exists(pid) => (Some(pid), "alive"),
        Some(pid) => (Some(pid), "dead"),
        None => (None, "untracked"),
    }
}

fn process_pid_exists(pid: u32) -> bool {
    #[cfg(unix)]
    {
        std::path::Path::new(&format!("/proc/{pid}")).exists()
    }
    #[cfg(not(unix))]
    {
        let _ = pid;
        false
    }
}

