    #[test]
    fn xiao_shu_action_request_schema_is_dry_run_only() {
        let tool = XiaoShuActionRequestTool::new(crate::Hub::builder().build());
        let schema = tool.schema();

        assert_eq!(schema.name, "xiao_shu_action_request");
        assert!(schema.description.contains("LLM-safe"));
        assert!(schema.description.contains("never directly"));
        assert!(schema.description.contains("Real audio still requires"));
        assert_eq!(
            schema.input_schema["properties"]["confirm"]["description"],
            "Dry-run confirmation flag. Even when true, this MCP tool does not emit audio."
        );
        assert_eq!(
            schema.input_schema["properties"]["enqueue"]["default"],
            false
        );
        assert!(schema.input_schema["properties"]["enqueue"]["description"]
            .as_str()
            .unwrap()
            .contains("does not emit audio"));
        assert_eq!(
            schema.input_schema["properties"]["list_queue"]["default"],
            false
        );
        assert!(
            schema.input_schema["properties"]["list_queue"]["description"]
                .as_str()
                .unwrap()
                .contains("read-only")
        );
        assert_eq!(schema.input_schema["properties"]["limit"]["default"], 20);
        assert_eq!(
            schema.input_schema["properties"]["intent"]["enum"][0],
            "voice_alert"
        );
    }

    #[test]
    fn drift_ratio_first_write_is_zero() {
        // Empty old → first write, no constraint.
        assert_eq!(
            agent_profile_diff_ratio("", "## Identity\n\nI am Claude."),
            0.0
        );
        assert_eq!(agent_profile_diff_ratio("   \n   \n", "anything"), 0.0);
    }

    #[test]
    fn drift_ratio_identical_is_zero() {
        let txt = "## Values\n\n- honesty\n- conservative mutations";
        assert_eq!(agent_profile_diff_ratio(txt, txt), 0.0);
    }

    #[test]
    fn drift_ratio_disjoint_is_one() {
        let old = "line one\nline two\nline three";
        let new = "alpha\nbeta\ngamma";
        assert!((agent_profile_diff_ratio(old, new) - 1.0).abs() < 1e-6);
    }

    #[test]
    fn drift_ratio_partial_change_is_bounded() {
        // 4 old lines, change 1 → ratio ~ 0.4 (1 removed + 1 added) / (4 + 1 union) = 2/5
        let old = "a\nb\nc\nd";
        let new = "a\nb\nc\ne";
        let r = agent_profile_diff_ratio(old, new);
        assert!(r > 0.3 && r < 0.5, "expected ~0.4, got {r}");
    }

    #[test]
    fn drift_ratio_pure_addition_grows_slowly() {
        // 3 old lines, add 1 → 1 new uniqueness, intersection=3, union=4 → 0.25
        let old = "a\nb\nc";
        let new = "a\nb\nc\nd";
        let r = agent_profile_diff_ratio(old, new);
        assert!((r - 0.25).abs() < 1e-6, "expected 0.25, got {r}");
    }

    #[test]
    fn drift_ratio_below_cap_passes() {
        // Add a Growth-marker style entry to a substantial profile.
        let old = (1..=20)
            .map(|i| format!("line {i}"))
            .collect::<Vec<_>>()
            .join("\n");
        let new = format!("{old}\nnew growth marker");
        let r = agent_profile_diff_ratio(&old, &new);
        assert!(r < AGENT_PROFILE_DRIFT_CAP, "expected < cap, got {r}");
    }

    #[test]
    fn drift_ratio_total_rewrite_blocked_by_cap() {
        let old = (1..=10)
            .map(|i| format!("old line {i}"))
            .collect::<Vec<_>>()
            .join("\n");
        let new = (1..=10)
            .map(|i| format!("new line {i}"))
            .collect::<Vec<_>>()
            .join("\n");
        let r = agent_profile_diff_ratio(&old, &new);
        assert!(
            r > AGENT_PROFILE_DRIFT_CAP,
            "total rewrite must exceed cap, got {r}"
        );
    }

    // ── Decision review trigger tests ───────────────────────────────────

    fn mk_decision(key: &str, importance: f64, tags: &[&str], updated_at: i64) -> MemoryRecord {
        MemoryRecord {
            key: key.into(),
            kind: "decision".into(),
            content: format!("First line for {key}.\nMore detail here."),
            tags: tags.iter().map(|s| s.to_string()).collect(),
            related_keys: Vec::new(),
            scope: None,
            created_at: updated_at,
            updated_at,
            last_accessed_at: updated_at,
            access_count: 0,
            importance,
            status: "active".into(),
            trigger_pattern: None,
            superseded_by: None,
        }
    }

    // ── ζ-11 compute_link_suggestions blacklist tests ──────────────────

    fn mk_mem(key: &str, kind: &str, content: &str, tags: &[&str]) -> MemoryRecord {
        MemoryRecord {
            key: key.into(),
            kind: kind.into(),
            content: content.into(),
            tags: tags.iter().map(|s| s.to_string()).collect(),
            related_keys: Vec::new(),
            scope: None,
            created_at: 0,
            updated_at: 0,
            last_accessed_at: 0,
            access_count: 0,
            importance: 0.5,
            status: "active".into(),
            trigger_pattern: None,
            superseded_by: None,
        }
    }

    fn mk_mem_scoped(
        key: &str,
        kind: &str,
        content: &str,
        tags: &[&str],
        scope: Option<&str>,
    ) -> MemoryRecord {
        let mut rec = mk_mem(key, kind, content, tags);
        rec.scope = scope.map(|s| s.to_string());
        rec
    }

    fn mk_search_hit_scoped(key: &str, scope: Option<&str>, score: f64) -> MemorySearchHit {
        MemorySearchHit {
            record: mk_mem_scoped(key, "lesson", "content content content content", &[], scope),
            score,
            cosine: Some(score as f32),
        }
    }

    fn mk_edge(from_key: &str, to_key: &str, edge_type: &str) -> MemoryEdge {
        MemoryEdge {
            from_key: from_key.into(),
            to_key: to_key.into(),
            edge_type: edge_type.into(),
            weight: 1.0,
        }
    }

    #[test]
    fn memory_search_scope_filter_is_strict_by_default() {
        let scoped = mk_mem_scoped(
            "scoped",
            "decision",
            "content content content content",
            &[],
            Some("project:/repo/a"),
        );
        let nested = mk_mem_scoped(
            "nested",
            "decision",
            "content content content content",
            &[],
            Some("project:/repo/a/sub"),
        );
        let other = mk_mem_scoped(
            "other",
            "decision",
            "content content content content",
            &[],
            Some("project:/repo/b"),
        );
        let global = mk_mem_scoped(
            "global",
            "decision",
            "content content content content",
            &[],
            Some("global"),
        );
        let unscoped = mk_mem(
            "unscoped",
            "decision",
            "content content content content",
            &[],
        );

        assert!(memory_search_scope_mode_matches(
            &scoped,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(memory_search_scope_mode_matches(
            &nested,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(memory_search_scope_mode_matches(
            &scoped,
            "project:/repo/a/sub",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(!memory_search_scope_mode_matches(
            &other,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(!memory_search_scope_mode_matches(
            &global,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(!memory_search_scope_mode_matches(
            &unscoped,
            "project:/repo/a",
            MemorySearchScopeMode::LocalOnly
        ));
        assert!(memory_search_scope_mode_matches(
            &global,
            "project:/repo/a",
            MemorySearchScopeMode::LocalPlusGlobal
        ));
        assert!(memory_search_scope_mode_matches(
            &unscoped,
            "project:/repo/a",
            MemorySearchScopeMode::LocalPlusGlobal
        ));
    }

