        assert!(cli_status_indicates_connected("Connected"));
        assert!(cli_status_indicates_connected("✔ Connected"));
        assert!(cli_status_indicates_connected("Connected (45 tools)"));
        assert!(cli_status_indicates_connected(
            "🟢 agent-bridge - Connected"
        ));
